(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-a-35b-hybrid-attention-mixture-of-ex-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-1\">一 · 现场：一条被显存预算掐住的服务链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-2\">二 · 旧方案的主流做法与它在 6GB 上的失效点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-3\">三 · 反量化内层：把精度损失换成指令预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-4\">四 · MoE 路由与分组 GEMM 在单卡上的组织代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-5\">五 · 为什么非改不可：旧栈的三条路径全部堵死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-6\">六 · 与 Blackwell 部署视角的接口：旧约束映射到新机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-7\">七 · 把“负载”当作显存预算的输入变量，而不是事后统计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-8\">八 · 输入长度分布决定 KV 压缩比的有效性，而非相反</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-9\">九 · 批大小是内核占用与显存的双重函数，连续批处理在此处退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-10\">十 · SLO 在单卡极端显存下应写成可行性约束，而非延迟目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-11\">十一 · 长尾的两个来源：长度长尾与专家热点长尾，测量口径不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-12\">十二 · 可核查的最小测量集：把上述口径落成一张表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-13\">十三 · 反量化内核的指令预算：4-bit 权重如何在寄存器里“活过来”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-14\">十四 · 累加精度的选择：FP16 累加为何在 MoE 分组 GEMM 里不够用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-15\">十五 · 从 FP16 到 NVFP4：Blackwell 上同一公式的硬件化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-16\">十六 · 2-SM MMA 与 TMEM：分组 GEMM 的 tile 形状被重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-17\">十七 · 第五代 Tensor Core 的精度档位与误差传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-18\">十八 · 把两代硬件的代价放在一张表里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-19\">十九 · 显存账本的三个账户：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-20\">二十 · KV 的两级压缩：混合注意力把增长曲线掰弯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-21\">二十一 · 分页、复用与卸载：把账本做成可调度结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-22\">二十二 · 带宽瓶颈在哪：反量化税与分组 GEMM 的读放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-23\">二十三 · 可复算的显存预算：把 6GB 拆成四块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-24\">二十四 · HBM3e 容量怎么算：Blackwell 上的同一本账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-25\">二十五 · 连续批处理在 6GB 预算下的可行边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-26\">二十六 · Chunked prefill：把首 token 的尖峰切成台阶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-27\">二十七 · 优先级与抢占：驱逐谁、重算多少</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-28\">二十八 · 分离式预填/解码在单卡上的退化形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-29\">二十九 · 尾延迟怎么压：从 P99 反推调度参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-30\">三十 · 时延与吞吐的取舍落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-31\">三十一 · 单卡零通信的基线：为什么这篇论文的并行章节从“不可用”写起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-32\">三十二 · TP 的通信账：每层两次集合通信与激活的临界尺寸</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-33\">三十三 · EP 与 All-to-All：MoE 推理的通信主战场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-34\">三十四 · PP 与 DP：边界传输与零通信的两种极端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-35\">三十五 · NIXL 与跨节点传输：当通信走出 NVLink 域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-36\">三十六 · 通信何时成为瓶颈：一个可操作的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-37\">三十七 · 精度塌陷：4-bit 反量化的误差放大路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-38\">三十八 · OOM：6GB 预算下的三类溢出与判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-39\">三十九 · 批抖动：路由负载不均如何传导为时延抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-40\">四十 · 尾延迟：长上下文与全注意力层的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-41\">四十一 · 静默降级：没有报错的性能与精度滑坡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-42\">四十二 · 回滚策略：把失败模式映射为可执行动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-43\">四十三 · 口径先于数字：这份材料能支撑什么、不能支撑什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-44\">四十四 · 硬件档位：Fermi 的四个“没有”如何定义指标含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-45\">四十五 · batch 与并发：6GB 预算下的可行域是一条窄带</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-46\">四十六 · 指标读法：TTFT/TPOT/吞吐/显存/功耗各自的有效性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-47\">四十七 · 哪些提升不可比：四类跨档位误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-48\">四十八 · 读表模板：把这份材料的数字放进正确的格子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-49\">四十九 · 迁移到 Blackwell 时真正要重写的三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-50\">五十 · 哪些模型结构会让这套方案直接失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-51\">五十一 · 规模上限：不是显存，是反量化指令吞吐与路由熵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-52\">五十二 · 领域迁移：哪些推理形态根本不该用这套方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-53\">五十三 · 迁移检查清单：把判断落到可执行的量上</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:567px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 566.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"484.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按 token 序列切分，嵌入与位置编码在低精度显存预算下完…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"484.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">混合注意力层按层类型分别执行全注意力或线性注意力，KV 仅对全注意力层…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"484.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">MoE 路由对每个 token 计算专家打分并选取 top-k 专家，…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"484.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">分组 GEMM 内核按专家聚合 token，权重从 4-bit 反量化…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"484.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出层与采样在受限显存下完成，逐 token 解码并返回响应。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-1\">一 · 现场：一条被显存预算掐住的服务链路</h3>\n<p>设想一个 2011 年遗留机房里的在线服务：一台工作站插着一张 Fermi 架构的 6GB 显卡，业务方要求在这台机器上跑一个 35B 级混合注意力 MoE 模型的推理接口。请求从网关进来，被切成 token 序列，逐 token 解码，再回写响应。这条链路上没有任何一个环节是宽裕的：嵌入表要占显存，位置编码要占显存，每一层的权重都要占显存，KV 还要占显存，而总预算只有 6GB。35B 参数哪怕按最激进的 4-bit 打包，权重本身就逼近 17.5GB 量级——单是这一项就已经把 6GB 预算击穿了三倍以上。这就是本工作的问题现场：它不是“能不能跑得快”的问题，而是“能不能装得下”的问题，容量是第一道闸门，带宽与指令吞吐是第二道闸门。</p>\n<p>把这个场景拆成可计价的系统量：显存占用 = 权重 + KV + 激活 + 内核工作区 + 框架开销。在 Fermi 上，框架开销与内核工作区无法像现代栈那样靠统一内存或分页迁移摊薄，因为 2011 年的硬件没有对应的迁移引擎，任何一次越界都直接表现为分配失败。于是工程上唯一可行的路径是把权重压到 4-bit 打包存放，让权重项从 17.5GB 量级压到约 4.4GB 量级（35B × 0.5 byte），剩下的 1.6GB 左右留给 KV、激活与工作区。这个算术不是精确预算表，而是说明为什么 4-bit 不是“优化选项”而是“入场券”：任何高于 4-bit 的权重格式都会让这条链路在第一个 token 之前就死掉。</p>\n<p>代价随之而来。Fermi 没有张量核心，也没有原生 NVFP4/FP8 数据路径，4-bit 权重不能直接被乘加单元消费，必须在计算前反量化。反量化的位置决定了代价落在哪里：放在全局显存里做，等于把权重读两遍，带宽翻倍；放在寄存器与共享内存里做，等于把反量化指令塞进内层循环，指令吞吐成为新的瓶颈。本工作选择后者，于是每一次分组 GEMM 的内层都同时承受“读 4-bit 打包字”和“解包成更高精度”两笔开销。这就是旧方案在新约束下的第一个硬痛点：低精度存储省下的是容量，付出的是带宽与指令预算。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-2\">二 · 旧方案的主流做法与它在 6GB 上的失效点</h3>\n<p>论文之前，推理栈的主流做法可以概括为三条默认假设。第一条：权重以 16-bit 或 8-bit 存放，靠硬件原生低精度路径（张量核心的 FP16/BF16/FP8 通道）完成矩阵乘，量化只是可选的加速手段。第二条：KV cache 按全注意力层线性增长，靠增大批大小摊薄权重读取的固定成本，用连续批处理把解码阶段的算力利用率拉起来。第三条：MoE 的专家并行靠多卡 All-to-All 把专家摊到不同设备上，单卡只驻留一部分专家权重。这三条假设在数据中心卡上成立，在 6GB Fermi 上逐条失效。</p>\n<p>第一条失效的直接后果是：没有原生低精度路径，8-bit 权重也无法被硬件直接消费，仍然要反量化；而 8-bit 权重在 6GB 里根本装不下 35B。第二条失效的后果是：KV 线性增长会迅速吃掉权重之外仅剩的那点预算，批大小被迫压到极小，权重读取的固定带宽成本无法被摊薄，解码阶段的算力利用率跌到谷底。第三条失效的后果是：单卡 6GB 下没有第二张卡可分，专家并行与 All-to-All 不适用，全部专家权重必须驻留本地，容量成为唯一瓶颈，通信开销为零但换不来任何容量收益。</p>\n<p>用公式把旧方案的代价写清楚。设权重总量为 $W$（字节），KV 单 token 占用为 $k$（字节/token），批大小为 $B$，上下文长度为 $L$，则显存约束为：</p>\n<div class=\"formula\">$$W + B\\cdot L\\cdot k + A_{\\text{act}} + A_{\\text{ws}} \\le 6\\,\\text{GB}$$</div>\n<p>在 16-bit 权重下 $W\\approx 70\\,\\text{GB}$，不等式左边第一项就已远超右端，无解。在 8-bit 下 $W\\approx 35\\,\\text{GB}$，仍无解。只有 4-bit 下 $W\\approx 17.5\\,\\text{GB}$ 量级——注意这个数仍然大于 6GB，所以单靠 4-bit 权重还不够，必须同时把 KV 压到可承受范围，这正是混合注意力结构存在的理由：全注意力层保留压缩 KV，线性注意力层以常数级状态替代增长型 cache，把 $B\\cdot L\\cdot k$ 这一项从随 $L$ 线性增长改为部分层常数、部分层压缩增长。容量约束被满足，代价是注意力表达能力的折损与实现复杂度的上升。</p>\n<p>再看吞吐侧的旧方案代价。解码阶段每个 token 的权重读取量约为 $W$（若全部专家都被触达），在 4-bit 下约 4.4GB 量级；Fermi 的显存带宽远低于现代卡，单 token 的权重搬运时间就构成了延迟下限。批处理本可以摊薄这笔固定成本：$B$ 个 token 共享一次权重读取，单 token 摊销带宽降为 $W/B$。但 6GB 预算把 $B$ 压到极小，摊销效应几乎不存在，于是延迟由“权重搬运 + 反量化指令”主导，吞吐由“每 token 一次完整权重扫描”主导。这就是旧方案在极端受限硬件上的核心痛点：批处理这条摊薄路径被容量掐断，带宽效率无法通过并发换回来。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-3\">三 · 反量化内层：把精度损失换成指令预算</h3>\n<p>4-bit 打包存储的具体机制是：每两个权重共享一个字节，高 4 位与低 4 位各存一个量化索引；反量化时按分组尺度 $s$ 还原，$\\hat{W}=s\\cdot \\mathrm{dequant}_4(W_q)$。分组尺度是这里的关键设计变量：尺度越细，量化误差越小，但尺度本身的存储与读取开销越大；尺度越粗，元数据越省，但组内动态范围被强行拉平，误差上升。材料未给出分组粒度，因此无法量化这一权衡，但机制上的代价是确定的——每一组尺度都要在反量化前被载入寄存器或共享内存，组数越多，内层循环里非乘加的指令占比越高。</p>\n<p>把内层循环的代价写成伪代码思路：对每个输出 tile，外层按专家分组遍历 token 块，内层沿 K 维展开，每次载入一个 4-bit 打包字，解包为两个索引，乘以组尺度，送入乘加。Fermi 的乘加单元没有低精度通道，解包与尺度乘法都是独立的整数/浮点指令，无法与乘加融合。于是内层循环的指令数约为纯 FP16 路径的数倍，而算力上限并未提高——这就是“反量化开销”的实质：它不是一次性的转换成本，而是摊在每一个 MAC 上的固定税。系统代价表现为：算力利用率被指令吞吐而非乘加吞吐决定，显存带宽被 4-bit 读取与尺度读取共同占用，两者叠加使实际可达吞吐低于按带宽估算的上界。</p>\n<p>具体例子：假设某一层某个专家的权重矩阵为 $d\\times d$，token 块含 $T$ 个 token。分组 GEMM 的计算量为 $2T d^2$ 次浮点运算，权重读取量为 $d^2/2$ 字节（4-bit）加尺度元数据。若 $T$ 很小（逐 token 解码、批大小受限），计算量相对权重读取量极小，内核完全落在带宽与反量化指令上；若 $T$ 变大，计算量上升，但 6GB 预算不允许 $T$ 变大。这个例子说明：在极端受限硬件上，分组 GEMM 的“分组”不是为了负载均衡，而是为了在极小 token 块下仍能按专家聚合、避免逐 token 的碎片化读取。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-4\">四 · MoE 路由与分组 GEMM 在单卡上的组织代价</h3>\n<p>MoE 前馈层的推理形态是：路由为每个 token 打分，选 top-k 专家，得到路由权重 $g_e(x)$，输出为 $y=\\sum_{e\\in\\mathrm{TopK}(x)} g_e(x)\\cdot \\mathrm{GEMM}(\\hat{W}_e,x)$。在数据中心栈里，这一步之后通常接 All-to-All，把 token 发到持有对应专家的设备上。在 6GB 单卡上，没有 All-to-All，全部专家权重驻留本地，路由之后要做的是本地重排：把 token 按专家分组，形成按专家聚合的 token 块，再逐专家调用分组 GEMM。重排本身要占显存与带宽——索引缓冲、token 块的临时副本、路由权重的中间结果，都要在 6GB 里找位置。</p>\n<p>代价有三笔。第一笔是容量：专家权重全部驻留意味着 $W$ 无法通过并行摊薄，4-bit 是唯一出路。第二笔是负载不均：路由分布未给出，但机制上热点专家会形成更长的 token 块，冷门专家形成极短的块，分组 GEMM 的 tile 利用率在冷门专家上塌陷，而热点专家又受显存带宽限制无法加速。第三笔是碎片化：逐 token 解码时每个 token 的路由结果只涉及 top-k 个专家，token 块极小，分组 GEMM 的启动开销与权重载入开销占比极高，内核占用率低。这三笔代价共同解释了为什么材料只能确认“容量约束被满足”，而无法给出吞吐数字——在极小批大小下，分组 GEMM 的效率由固定开销主导，任何吞吐数字都高度依赖未给出的架构参数。</p>\n<p>用公式表达分组 GEMM 的有效算力利用率：设专家 $e$ 的 token 块大小为 $T_e$，权重矩阵为 $d\\times d$，则该专家的算术强度约为 $2T_e d^2 / (d^2/2 + \\text{meta})$，当 $T_e$ 很小时算术强度趋近于与 $T_e$ 成正比的小量，内核落在带宽与指令边界上。系统代价是：增大 $T_e$ 需要更大批大小，更大批大小需要更多 KV 预算，更多 KV 预算与权重预算在 6GB 里直接冲突。这是一个闭环的死结，混合注意力压缩 KV 是解开这个死结的唯一杠杆。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-5\">五 · 为什么非改不可：旧栈的三条路径全部堵死</h3>\n<p>把旧栈的三条路径逐条对照 6GB Fermi，结论是全部堵死。路径一“靠硬件低精度通道”：Fermi 没有张量核心，也没有 NVFP4/FP8，硬件不提供任何低精度乘加路径，量化必须由软件完成，反量化税无法回避。路径二“靠批处理摊薄权重读取”：KV 线性增长吃光预算，批大小被压到极小，摊薄效应消失，解码延迟由权重搬运主导。路径三“靠专家并行扩容”：单卡无第二设备可分，All-to-All 不适用，专家权重必须全部本地驻留，容量成为唯一瓶颈。</p>\n<p>三条路径堵死之后，剩下的工程空间只有三个方向：把权重压到 4-bit 并手写反量化内核；用混合注意力把 KV 从线性增长改为部分常数、部分压缩；把 MoE 专家计算组织为按路由分组的分组 GEMM，在极小 token 块下仍能聚合。这三个方向正是本工作的核心机制，也是它“非改不可”的理由——不是追求性能，而是在容量硬约束下维持一条能跑通的链路。代价是明确的：算力受显存带宽与反量化指令双重限制，批大小与上下文长度极紧，长上下文与高并发 SLO 无法满足，材料未给出失败模式的量化数据。</p>\n<p>具体例子：一个长上下文请求进来，KV 预算在全注意力层按压缩精度增长，线性注意力层以常数状态承接；当序列长度超过某个由 6GB 预算决定的阈值时，KV 项挤占权重与激活的空间，分配失败或被迫缩小批大小。这个阈值材料未给出，但机制上它由 $W$、$k$、压缩精度与工作区开销共同决定，是这条链路最脆弱的边界。工程判断是：这类部署的可用性不取决于峰值吞吐，而取决于在最坏请求形态下能否不触发显存分配失败；本工作把容量约束推到极限，但没有给出边界数据，因此其工程价值在于展示了可行性，而非提供了可复用的容量规划方法。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-6\">六 · 与 Blackwell 部署视角的接口：旧约束映射到新机制</h3>\n<p>对 Blackwell 读者，这一部分的价值不是复述 Fermi 的窘境，而是把旧约束映射到新机制上，看清哪些代价被硬件消除了、哪些被转移了。4-bit 打包存储在 Fermi 上要手写反量化，是因为没有原生低精度路径；在 SM100/SM103 上，NVFP4 提供了硬件级的 4-bit 乘加与缩放因子路径，反量化税从指令预算转移到硬件数据通路，tcgen05 与 TMEM 又把矩阵乘的累加与操作数管理从寄存器压力中解放出来。这意味着同一份“4-bit 权重 + 分组尺度”的设计，在 Blackwell 上的代价结构完全不同：带宽仍是瓶颈，但指令吞吐不再是内层循环的主导项。</p>\n<p>KV 压缩的映射同样清晰：Fermi 上用混合注意力把 KV 压到可承受范围，是因为 6GB 预算不允许全注意力层的线性增长；在 Blackwell 上，KV cache 的容量压力被更大的显存与分离式预填/解码架构缓解，但长上下文与高并发下的 KV 带宽仍然是核心成本，混合注意力与压缩 KV 的思路在新硬件上仍有位置，只是从“容量救命”变为“带宽与容量双重优化”。MoE 分组 GEMM 的映射则是：Fermi 上的分组是为了在单卡极小批大小下聚合 token；Blackwell 上的分组 GEMM 与专家并行、All-to-All 结合，分组的目的从“避免碎片化”变为“配合通信与负载均衡”。</p>\n<p>需要说清的边界是：本工作不涉及专家并行与 All-to-All，单卡 6GB 下通信开销为零但容量是唯一瓶颈；这个前提在 NVL72 这类多卡域上不成立，专家并行的通信代价与负载均衡成为新的主导项。因此把本工作的结论直接迁移到 Blackwell 部署是危险的——它能证明“4-bit 权重 + 混合注意力 + 分组 GEMM”在极端容量约束下可运行，但不能证明这套组合在有大显存、有 NVFP4、有 tcgen05 的环境里仍然是最优解。工程判断应落在：把 4-bit 分组尺度设计、KV 压缩比例、分组 GEMM 的 tile 组织当作可迁移的设计变量，把反量化内核的手写实现当作不可迁移的历史代价。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-7\">七 · 把“负载”当作显存预算的输入变量，而不是事后统计</h3>\n<p>在 6GB Fermi 上讨论请求形态，第一件事不是画 QPS 曲线，而是把请求的输入长度、并发数与批大小写成一条显存恒等式。权重以 4-bit 打包后仍占据固定的一大块，KV 只存在于全注意力层，线性注意力层以常数级状态替代增长型 cache。于是单请求的 KV 占用近似正比于全注意力层数与输入长度，而总占用是批内所有请求之和。可核查的口径是：给定权重驻留量 W4、每 token 每全注意力层的 KV 字节数 k、全注意力层数 L、批大小 B 与批内最长序列长度 S，显存约束写成</p>\n<div class=\"formula\">$$W_{4} + B\\cdot L\\cdot k\\cdot S + A_{\\text{act}} + M_{\\text{kernel}} \\le 6\\,\\text{GB}$$</div>\n<p>其中 A_act 是激活与反量化临时缓冲，M_kernel 是内核占用与碎片。这条式子把“负载形态”从观测量变成了约束项：S 与 B 不是独立可调的旋钮，而是被 6GB 硬性绑在一起。工程判断也因此变得直接——在权重不可再压的前提下，任何长输入请求都必须以牺牲并发为代价，反之亦然。材料未给出 k、L 与 W4 的具体数值，因此这里只能给出结构，不能给出配额；但口径本身可核查：只要记录每次请求的 S、B 与实测显存峰值，就能反解出实际可用的 k·L 乘积，从而判断混合注意力中全注意力层的比例是否与负载匹配。</p>\n<p>具体例子：一个 8K token 的输入与一个 512 token 的输入，在同一批内共存时，批的显存占用由前者主导，后者几乎“免费”搭车；但若调度器按平均长度做容量规划，就会在长请求到达时触发显存不足。这正是长尾输入在极端显存下的真实代价：不是平均吞吐下降，而是批的可行性被单个最长请求否决。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-8\">八 · 输入长度分布决定 KV 压缩比的有效性，而非相反</h3>\n<p>混合注意力的收益不是均匀的。线性注意力层以常数级状态替代增长型 cache，全注意力层保留压缩 KV，因此 KV 随长度的斜率只由全注意力层贡献。设全注意力层占比为 ρ，则每 token 的 KV 增量约为 ρ·k。当输入长度分布偏向短请求时，ρ 的取值对显存影响有限，压缩收益主要体现在“能开更大批”；当分布偏向长请求时，ρ 直接决定单请求能否被接纳。可核查的测量口径是分层统计：按输入长度分桶（例如 ≤512、512–2K、2K–8K、>8K），分别记录每桶的请求数、实测显存峰值、批大小与解码 token 速率，而不是只报全局平均。</p>\n<p>这里有一个反向约束：负载形态也会被方案塑造。若实现选择更高的 ρ 以保住长上下文质量，则在 6GB 下可接纳的并发被压低，调度器不得不更激进地拆分长请求或排队，长尾延迟被放大；若选择更低的 ρ，短请求吞吐上升，但长输入请求可能直接被拒绝或截断。材料未给出 ρ 与长度分布，因此无法判断该实现的实际取舍，但可核查的口径是明确的：把 ρ 作为自变量，测出“可接纳的最大 S×B 乘积”，再与真实请求分布对照，才能判断压缩比是否被负载用满。</p>\n<p>具体机制上，逐 token 解码意味着 KV 在解码阶段持续被读取而非一次性写入，因此长请求的代价不只是容量，还有每步解码对压缩 KV 的带宽读取。Fermi 缺少张量核心，解码步的算力主要受显存带宽与反量化指令开销限制，长上下文请求会把带宽压力集中到 KV 读取上，与权重反量化争夺同一带宽预算。这是“负载塑造方案”的另一面：长度分布越偏长，方案越需要在 KV 压缩精度与反量化开销之间重新分配带宽。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-9\">九 · 批大小是内核占用与显存的双重函数，连续批处理在此处退化</h3>\n<p>现代 serving 框架用连续批处理（continuous batching）把解码步的批填满，靠的是 KV 分页与较大的显存余量。在 6GB Fermi 上，这条路径被两件事掐住：一是 KV 无法分页到显存之外（无 NVLink、无主机侧高速互连的可用预算），二是分组 GEMM 内核的占用受寄存器与共享内存限制。反量化在寄存器/共享内存中完成，每个专家的 4-bit 权重块被加载后展开，展开后的临时缓冲与 token 块大小共同决定单内核能容纳多少 token。批大小因此不是“显存够就能加”，而是“内核占用够才能加”。</p>\n<p>可核查的口径是把批大小扫描做成二维表：横轴为批内 token 总数（而非请求数），纵轴为专家分组后的最大单组 token 数，记录每格的解码步延迟与显存峰值。MoE 路由的 top-k 选择会让 token 在专家间分布不均，最大单组 token 数往往远大于平均值，分组 GEMM 的尾组成为延迟瓶颈。于是“有效批大小”应由最大组决定，而不是由总 token 数决定。这条口径在材料未给出专家数与 top-k 的情况下依然可操作：只要记录每次解码步的组大小直方图，就能看出负载不均的程度。</p>\n<p>具体例子：若一批 32 个请求各自产生 1 个解码 token，路由后某些专家收到 20 个 token、另一些只收到 2 个，则分组 GEMM 的实际并行度由 20 那一组决定，2 那一组的权重加载几乎不产生有效算力。此时增大批大小只会加剧不均衡，吞吐不升反降。这是“方案反过来限制负载”的典型：调度器若按请求数扩容，会在专家热点上撞墙；正确做法是按组大小分布做准入控制，把新请求推迟到组分布更均匀的步。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-10\">十 · SLO 在单卡极端显存下应写成可行性约束，而非延迟目标</h3>\n<p>常规 SLO 是首 token 延迟（TTFT）与每 token 延迟（TPOT）的百分位目标。在这套实现里，TTFT 的主要成分是预填阶段对输入 token 的注意力与 MoE 计算，TPOT 的主要成分是解码步的权重反量化与分组 GEMM。由于批大小受显存与内核占用双重约束，排队延迟往往比计算延迟更主导长尾。可核查的口径是把 SLO 拆成三段：排队时间、预填时间、解码步时间，分别记录 P50 与 P99，并记录被拒绝或截断的请求比例。材料未给出 SLO 数值，因此不能声称满足任何目标；但可以确认的是，在 6GB 下“拒绝率”本身应作为一等指标，因为容量约束会以拒绝而非降速的形式表现出来。</p>\n<p>公式上，单请求的端到端时间可写成</p>\n<div class=\"formula\">$$T = T_{\\text{queue}} + T_{\\text{prefill}}(S) + N_{\\text{out}}\\cdot T_{\\text{step}}(B, G_{\\max})$$</div>\n<p>其中 N_out 是输出 token 数，G_max 是该步分组 GEMM 的最大组大小。这个式子的工程含义是：TPOT 不是常数，它随批内组分布波动；因此按平均 TPOT 做容量规划会系统性低估长尾。可核查的做法是记录每步的 G_max 与 T_step，画出两者的散点，判断延迟是否由组不均衡而非总算力决定。</p>\n<p>具体机制上，预填阶段的长输入会一次性产生大量 token 的路由与分组 GEMM，其显存峰值远高于解码步；若调度器把预填与解码混在同一批，预填的峰值会挤掉解码的 KV 预算。分离式预填/解码在现代 Blackwell 部署中是标准手段，但在这套单卡实现里不可用（无独立预填池），因此只能靠时间上错开：先做预填、再进入解码循环。这直接塑造了负载形态——长输入请求的到达节奏决定了系统能否维持稳定的解码批。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-11\">十一 · 长尾的两个来源：长度长尾与专家热点长尾，测量口径不同</h3>\n<p>长度长尾来自输入分布的重尾：少数请求占据大部分 token 预算，且它们的预填峰值决定显存上限。专家热点长尾来自路由分布的不均：某些专家被高频选中，其 4-bit 权重块被反复加载与反量化，形成带宽热点。两者对系统的作用点不同：前者作用于容量与预填，后者作用于解码步的分组 GEMM 尾组。可核查的口径因此要分开：长度长尾用“按长度分桶的显存峰值与拒绝率”衡量；专家热点用“每专家每步的 token 数直方图与对应内核时间”衡量。材料未给出路由分布，因此无法判断热点程度，但口径可操作。</p>\n<p>反向约束在这里最明显：若专家热点严重，方案会被迫增大分组 GEMM 的组粒度或引入容量因子（capacity factor）来截断溢出 token，而截断会改变模型输出分布——这不是性能取舍，而是质量取舍。在 6GB 下，容量因子若设得小，溢出 token 被丢弃或走残差路径，长尾请求的质量下降；若设得大，显存与内核占用上升，批大小下降。可核查的测量是把容量因子作为自变量，同时记录吞吐、显存峰值与（若有）质量指标，而不是只报吞吐。材料未给出容量因子与质量指标，因此这里只能给出方法，不能给出结论。</p>\n<p>具体例子：一个长输入请求在预填时产生大量 token，路由后某专家组远超容量因子，溢出 token 被截断；该请求的输出质量在长尾处退化，而短请求不受影响。这种退化在平均指标上不可见，只有按长度分桶的质量统计才能暴露。这正是“负载塑造方案、方案限制负载”的闭环：负载的长尾迫使方案设容量因子，容量因子又反过来在长尾处限制负载的可服务性。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-12\">十二 · 可核查的最小测量集：把上述口径落成一张表</h3>\n<p>在材料未给出任何吞吐、延迟与精度数字的前提下，唯一能站住脚的是测量口径本身。最小集包括：每请求的输入长度、输出长度、到达时间与结束时间；每解码步的批内 token 总数、分组 GEMM 最大组大小、显存峰值与步时间；每请求是否被拒绝或截断；按长度分桶的上述统计。由此可导出三个判据：其一，显存恒等式是否被满足（实测峰值是否贴近 6GB）；其二，解码步时间是否由 G_max 主导（散点斜率是否显著）；其三，拒绝率是否随长度分桶单调上升（容量约束是否以拒绝形式表现）。</p>\n<p>这三个判据不需要架构参数就能计算，因此适合作为该实现的复现口径。它们也直接对应 Blackwell 部署的对照点：在现代硬件上，KV 可分页、预填解码可分离、NVFP4 有原生路径，同样的负载形态会表现为不同的瓶颈（带宽、互连或调度），但“按长度分桶、按组大小分桶、把拒绝率当一等指标”这套口径是共通的。工程判断落在具体机制上：在 6GB Fermi 上，负载形态的第一约束是显存恒等式中的 S×B 乘积，第二约束是分组 GEMM 的 G_max，第三约束才是算力；任何容量规划若从算力出发，都会在这套实现上给出错误的批大小与错误的 SLO。</p>\n<p>具体到一次请求的生命周期：到达时按长度分桶决定是否接纳，接纳后预填阶段的显存峰值决定是否需要单独成批，解码阶段按 G_max 决定是否推迟新请求加入当前批。这条准入逻辑本身就是“方案限制负载”的体现——它不是被动统计，而是主动用测量口径把负载塑造成显存与内核能承受的形状。材料未给出该逻辑的实现细节，但口径与判据足以让读者在自己的复现中落地。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-13\">十三 · 反量化内核的指令预算：4-bit 权重如何在寄存器里“活过来”</h3>\n<p>Fermi 上没有 NVFP4 的硬件解包通路，也没有 FP8 的乘加单元，因此 4-bit 权重从显存到乘加单元之间必须经过一条完全由手写指令铺出来的路。打包格式决定了这条路的长短：若把 8 个 4-bit 权重压进一个 32-bit word，一次 <code>ld.global.v4.u32</code> 取回 128 bit 即 32 个权重，随后每个权重需要一次移位与一次掩码才能还原为整型，再乘以分组尺度 <em>s</em> 转成 FP16 或 FP32 才能进入 FFMA。这条链上，反量化的算术指令数与权重数成正比，而 Fermi 的 FFMA 吞吐与整数移位吞吐共享发射端口，因此反量化不是“免费的解压”，它直接吃掉本可用于矩阵乘的指令槽。</p>\n<p>把这一步写成伪代码，代价就清楚了：</p>\n<div class=\"formula\">$$\\text{for } j \\text{ in } 0..7:\\quad q_j = (w \\gg 4j)\\ \\&amp;\\ 0\\mathrm{xF};\\quad \\hat{w}_j = s_g \\cdot (q_j - z_g)$$</div>\n<p>其中 <em>s<sub>g</sub></em>、<em>z<sub>g</sub></em> 是按分组共享的尺度与零点，分组粒度越小，尺度越多、显存里多出的元数据越多，但组内动态范围越窄、量化误差越小。这是一个纯显存—精度交换：6GB 预算下，元数据每增加一个 FP16 尺度就多占 2 字节，而每 32 个权重才摊到一次尺度读取，因此分组粒度不能无限细。工程判断是：分组尺度应存在共享内存或常量缓存中按块复用，避免每个线程重复从显存取尺度——在带宽受限的 Fermi 上，重复取尺度会把反量化从指令受限推向带宽受限。</p>\n<p>具体例子：一个专家权重矩阵若以 4-bit 存放，反量化到 FP16 后做 GEMM，则每读 1 字节权重需产出 4 字节激活精度的操作数，读放大比为 4:1；这意味着即便权重读取只占一次，反量化后的寄存器压力与共享内存占用都按 4 倍膨胀。6GB 显存能装下 35B 的 4-bit 权重，但片内存储装不下反量化后的整块权重，因此必须分块流式反量化，块大小由共享内存容量与寄存器文件决定，而不是由 GEMM 的算术强度决定。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-14\">十四 · 累加精度的选择：FP16 累加为何在 MoE 分组 GEMM 里不够用</h3>\n<p>反量化后的乘加需要一个累加器精度。Fermi 的 FFMA 以 FP32 累加为常态，FP16 存储、FP32 累加是当时可行的折中；若强行用 FP16 累加，35B 级模型的专家输出在 top-k 加权求和时会累积可观的舍入误差，尤其是路由权重 <em>g<sub>e</sub>(x)</em> 本身是 softmax 输出、量级差异大，低精度累加会让小权重专家的贡献被吞掉。误差的量级可以用一个简单的界来估计：</p>\n<div class=\"formula\">$$\\epsilon_{\\text{acc}} \\approx \\sqrt{K}\\cdot u\\cdot \\sum_{i}|a_i b_i|,\\quad u = 2^{-p}$$</div>\n<p>这里 <em>K</em> 是归约长度，<em>u</em> 是累加精度的单位舍入，<em>p</em> 是尾数位数。FP16 的 <em>p</em>=10，FP32 的 <em>p</em>=23，两者相差约 13 个二进制数量级；在归约长度达到数千的隐藏维度上，FP16 累加的误差界比 FP32 高出三个数量级以上。这不是理论洁癖：MoE 的输出是多个专家 GEMM 结果的加权和，若每个专家的累加都带偏，加权和会把偏差叠加而不是抵消。因此在该实现里，4-bit 权重反量化到 FP16 做乘法、以 FP32 累加，是容量与精度之间被迫选定的工作点。</p>\n<p>代价在吞吐侧：FP32 累加意味着每个乘加要占用一个 32-bit 寄存器作为累加器，寄存器压力是 FP16 累加的两倍，直接压低 occupancy；在 Fermi 这种寄存器文件本就紧张的架构上，occupancy 下降会进一步暴露显存延迟。具体例子：一个 128×128 的权重块，若每线程持有 8 个 FP32 累加器，则每线程至少 8 个寄存器专用于累加，加上反量化临时量与地址寄存器，单线程寄存器数很容易逼近上限，编译器被迫 spill 到本地内存——本地内存走显存，等于把 GEMM 变成带宽测试。这就是为什么分块大小与线程级 tile 必须按寄存器预算反推，而不是照搬现代张量核心内核的 tile 形状。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-15\">十五 · 从 FP16 到 NVFP4：Blackwell 上同一公式的硬件化</h3>\n<p>把上面两节的公式搬到 Blackwell，变化不在于数学，而在于每一项由谁执行。NVFP4 的 E2M1 元素与每 16 元素共享的 FP8 尺度（以及可选的二级尺度）在硬件里完成解包与缩放，反量化的移位、掩码、乘尺度三步从指令流里消失，转而由 Tensor Core 的输入通路承担。同一句 <em>Ŵ = s · dequant₄(W<sub>q</sub>)</em> 在 Fermi 上是几十条整数与浮点指令，在 Blackwell 上是一次 MMA 指令的输入准备。代价的转移很明确：Fermi 的反量化开销是算力侧的指令吞吐，Blackwell 的量化开销是精度侧的表达能力——E2M1 只有 4 个尾数位级别的动态范围，尺度分组必须足够细才能不让大权重吃掉小权重。</p>\n<p>累加精度的硬件化同样如此。tcgen05 的 MMA 在 Tensor Memory 中累加，累加器精度由指令描述符指定，FP32 累加不再消耗通用寄存器文件，而是占用 TMEM 的列。这意味着第二节里“FP32 累加压低 occupancy”的约束在 Blackwell 上被解除：occupancy 由 TMEM 容量与 warp 调度决定，而非寄存器文件。工程判断随之改变——在 Fermi 上必须缩小 tile 保寄存器，在 Blackwell 上可以放大 tile 吃满 TMEM，因为累加器不再与反量化临时量争抢同一份寄存器。</p>\n<p>具体例子：一个 MoE 专家的分组 GEMM，在 Fermi 上按 32×32 或 64×64 的 tile 流式反量化，每块都要重新走一遍移位掩码链；在 Blackwell 上同一专家权重以 NVFP4 存放，2-SM MMA 让两个 SM 协作承担一个更大的 tile，权重从 HBM 经 TMA 直接进共享内存再进 Tensor Core，反量化在数据通路上完成。前者的瓶颈是每权重指令数，后者的瓶颈是 HBM 带宽与 TMEM 容量——同样是“权重放不下”的问题，解法从指令工程变成了数据搬运工程。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-16\">十六 · 2-SM MMA 与 TMEM：分组 GEMM 的 tile 形状被重新定义</h3>\n<p>MoE 的分组 GEMM 有一个固有难点：每个专家的 token 数不等，tile 的 M 维（token 维）随路由结果波动，负载不均会让部分 tile 空转。Fermi 上的手写内核只能用固定 tile 加边界判断，空转的 lane 照样消耗指令。Blackwell 的 2-SM MMA 把两个 SM 的 Tensor Core 与 TMEM 联合成一个更大的计算单元，tile 的 N 维或 K 维可以跨 SM 拼接，于是分组 GEMM 可以把多个小专家的权重拼进同一个 MMA 的 K 维，用一次指令覆盖多个专家的归约，减少小 tile 的空转比例。代价是同步：2-SM MMA 要求两个 SM 的 TMEM 分配与指令发射严格对齐，任一 SM 的 warp 调度抖动都会让另一方等待。</p>\n<p>TMEM 的容量约束直接决定同时驻留多少个累加 tile。分组 GEMM 若按专家分批，每批的累加器占 TMEM 列数，批数越多、每批 tile 越大，TMEM 越紧张；一旦 TMEM 溢出，只能回退到寄存器累加，等于放弃 tcgen05 的收益。因此调度器必须在“每批塞更多专家以减少启动开销”与“每批 tile 更小以留出 TMEM”之间取舍。这个取舍在 Fermi 上不存在——那里根本没有 TMEM，只有寄存器与共享内存的硬墙；Blackwell 把墙换成了另一种形状，但没有取消墙。</p>\n<p>具体例子：路由后若某专家只分到极少 token，Fermi 内核要么为它单独发一次小 GEMM（启动开销占比高），要么把它并入通用 tile 让多数 lane 空转；Blackwell 上可把该专家的权重作为 K 维的一段拼入邻近专家的 MMA，用 2-SM 的宽度吸收这个小块。代价是这次 MMA 的 K 维被拉长，归约长度增加，FP32 累加的误差界按第二节的公式随 <em>√K</em> 增长——精度与负载均衡在指令层面被绑在了一起。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-17\">十七 · 第五代 Tensor Core 的精度档位与误差传播路径</h3>\n<p>Blackwell 的 Tensor Core 提供多档输入精度：FP16/BF16、FP8（E4M3/E5M2）、NVFP4，累加精度可选 FP32 或更低。档位选择的实质是把误差从一条路径搬到另一条路径。BF16 与 FP16 的取舍是动态范围对尾数：BF16 的 8 位指数能容纳 MoE 路由权重与激活的宽动态范围，但 7 位尾数的舍入误差比 FP16 大；FP8 的 E4M3 在尾数与范围之间再切一刀，E5M2 则把范围让给指数。对 35B 级 MoE，激活的离群值会主导量化误差，因此尺度分组必须按通道或按块自适应，否则一个离群通道会把整组的有效位数吃掉。</p>\n<p>误差传播可以写成一条链：权重 4-bit 量化误差 → 反量化尺度误差 → 乘加舍入 → 累加舍入 → 路由加权求和。每一环的误差界不同，但最终都汇入同一句输出公式：</p>\n<div class=\"formula\">$$y=\\sum_{e\\in\\mathrm{TopK}(x)} g_e(x)\\cdot \\mathrm{GEMM}(\\hat{W}_e,x),\\quad \\hat{W}_e = s_e\\cdot \\mathrm{dequant}(W_{q,e})$$</div>\n<p>逐项解释：<em>g<sub>e</sub>(x)</em> 是路由权重，其 softmax 归一化意味着误差在小权重专家上被压缩、在大权重专家上被放大；<em>GEMM(Ŵ<sub>e</sub>, x)</em> 的误差由 <em>Ŵ<sub>e</sub></em> 的量化误差与 <em>x</em> 的激活精度共同决定；求和则把 top-k 个专家的误差按权重叠加。关键判断是：MoE 的误差不会因为专家多而平均掉，因为 top-k 选择本身是离散的，路由边界附近的 token 可能因量化误差改变专家选择，产生不连续的输出跳变——这是稠密模型没有的失败模式。</p>\n<p>代价在系统侧表现为精度档位与吞吐的兑换率。FP8 相对 BF16 把权重带宽减半，但需要每通道或每块的缩放因子，缩放因子的读取与广播在分组 GEMM 里是额外开销；NVFP4 再把带宽减半，代价是尺度分组更细、元数据占比更高。在 6GB 的 Fermi 上，这个兑换率被显存容量锁死——只能用 4-bit，没有选档位的自由；在 Blackwell 上，档位自由换来的是容量规划的自由度：同样的 HBM 可以装下更多专家或更长 KV，但每个档位都要用精度预算去换。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-18\">十八 · 把两代硬件的代价放在一张表里</h3>\n<p>下表只对照本部分涉及的机制，不复述架构参数。每一行对应一个工程判断：同一句公式在两代硬件上由不同的单元执行，瓶颈从指令吞吐迁移到数据搬运与片内存储容量。</p>\n<table class=\"mini\"><thead><tr><th>机制</th><th>Fermi 6GB 手写路径</th><th>Blackwell（SM100/SM103）</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>4-bit 反量化</td><td>移位+掩码+乘尺度，逐权重指令</td><td>NVFP4 硬件解包与尺度应用</td><td>Fermi：指令吞吐；Blackwell：E2M1 动态范围</td></tr>\n<tr><td>累加精度</td><td>FP32 累加占通用寄存器</td><td>FP32 累加驻留 TMEM</td><td>Fermi：occupancy 下降；Blackwell：TMEM 容量</td></tr>\n<tr><td>分组 GEMM tile</td><td>固定 tile + 边界判断，小专家空转</td><td>2-SM MMA 跨 SM 拼接 K 维</td><td>Fermi：lane 利用率；Blackwell：双 SM 同步</td></tr>\n<tr><td>精度档位</td><td>无档位可选，只有 4-bit 权重</td><td>FP16/BF16/FP8/NVFP4 可选</td><td>档位越低压带宽、越吃尺度元数据</td></tr>\n</tbody></table>\n<p>具体例子把表里的判断落地：若把一个专家的权重块从 FP16 换成 NVFP4，权重读取字节数降到四分之一，但每 16 个元素要多读一个 FP8 尺度，元数据开销约 6%；在带宽受限的 GEMM 里这笔账划算，在指令受限的 Fermi 手写内核里则不成立，因为那里没有硬件解包，省下的带宽会被反量化指令吃掉。这就是为什么该工作不能把 Blackwell 的 NVFP4 经验直接搬回 Fermi，也不能把 Fermi 的反量化内核直接移植到 Blackwell——两边的瓶颈项根本不在同一个位置。</p>\n<p>工程判断落在最后一点：分组 GEMM 的 tile 形状与累加精度必须由片内存储的容量反推，而不是由权重的位宽反推。Fermi 上寄存器文件是那个容量，Blackwell 上 TMEM 是那个容量；位宽只决定权重从 HBM 到片内的搬运量，不决定片内如何组织计算。把这条顺序搞反，就会写出在 Fermi 上 spill、在 Blackwell 上 TMEM 溢出的内核。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-19\">十九 · 显存账本的三个账户：权重、激活、KV</h3>\n<p>在 6GB 的 Fermi 卡上做 35B MoE 推理，第一件事不是写内核，而是把显存当成一本必须逐字节对账的账本。这本账本只有三个账户：权重、激活、KV cache。三者不是并列关系，而是互相挤占——权重多占一兆，KV 就少一兆，批大小就掉一格。工程上必须先把权重账户钉死，再让 KV 账户在剩余空间里做弹性分配，激活账户则作为每次前向的临时透支项，用完即还。</p>\n<p>权重账户的算法是确定的：35B 参数以 4-bit 打包，每参数半个字节，理论下限是 35×10⁹×0.5 B ≈ 17.5 GB。这个数字本身就超过 6GB 四倍，所以“全部驻留”在物理上不成立。论文的做法不是把 35B 全塞进去，而是靠 MoE 的稀疏激活把“常驻集”和“按需集”分开：路由只激活 top-k 专家，非激活专家的权重可以留在显存外的后备存储，按专家粒度换入。于是权重账本要写成一个分段函数：</p>\n<div class=\"formula\">$$M_{W}=\\underbrace{M_{\\text{shared}}}_{\\text{注意力+嵌入+路由}}+\\underbrace{k\\cdot M_{e}}_{\\text{活跃专家}}+\\underbrace{M_{\\text{staging}}}_{\\text{换入缓冲}}$$</div>\n<p>其中 $M_e$ 是单专家 4-bit 权重字节数，$k$ 是 top-k，$M_{\\text{staging}}$ 是为换入准备的暂存区。这个式子的工程含义是：批大小和上下文长度不是独立超参，而是 $M_W$ 确定后剩下的余量函数。材料没有给出层数、专家数与隐藏维度，所以 $M_e$ 无法算出绝对值，但账本结构是可复算的——只要给定任一架构参数，就能把三项填满并检查是否溢出 6GB。</p>\n<p>激活账户是短时透支项。Fermi 没有张量核心，反量化后的权重必须落到寄存器与共享内存，激活也要以更高精度参与 GEMM。一次分组 GEMM 的激活占用大致是 token 块大小 × 隐藏维度 × 精度字节，且随批大小线性增长。这就是为什么批大小在 6GB 上被压得极低：激活不是常数，它随并发请求数放大，而权重和 KV 是“存量”，激活是“流量”。工程判断上，先保权重与 KV 的存量，再让激活在剩余空间里做小批量滚动，是这套实现能跑起来的前提。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-20\">二十 · KV 的两级压缩：混合注意力把增长曲线掰弯</h3>\n<p>KV cache 是解码阶段唯一随序列长度线性增长的账户。标准全注意力的 KV 占用为：</p>\n<div class=\"formula\">$$M_{KV}=2\\cdot L_{\\text{full}}\\cdot H_{kv}\\cdot d_{h}\\cdot S\\cdot b\\cdot p_{kv}$$</div>\n<p>其中 $L_{\\text{full}}$ 是全注意力层数，$H_{kv}$ 是 KV 头数，$d_h$ 是每头维度，$S$ 是序列长度，$b$ 是批大小，$p_{kv}$ 是每元素字节数。这个式子的关键不是绝对值，而是它对 $S$ 和 $b$ 的双线性依赖——长上下文与高并发在 KV 账户上是乘法关系，不是加法关系。6GB 卡上，任何让 $S\\cdot b$ 自由增长的方案都会立刻撞墙。</p>\n<p>论文用混合注意力把这个乘积拆成两段。全注意力层保留压缩后的 KV，线性注意力层则用常数级状态替代增长型 cache：线性注意力的状态大小与序列长度无关，只与头维度和状态维度有关。于是 KV 账本变成：</p>\n<div class=\"formula\">$$M_{KV}=2\\cdot L_{\\text{full}}\\cdot H_{kv}\\cdot d_{h}\\cdot S\\cdot b\\cdot p_{kv}+\\sum_{l\\in\\text{linear}}M_{\\text{state},l}$$</div>\n<p>第二项是常数，不随 $S$ 增长。工程代价是：线性注意力层牺牲了一部分全注意力的表达能力，换来的是 KV 增长曲线从线性变成“部分线性+常数”。在 6GB 预算下，这个交换是必须的——如果全部用全注意力，KV 会在几百个 token 内吃光剩余显存，批大小只能退到 1，吞吐趋近于零。混合比例决定了“长上下文能撑多长”与“批能开多大”之间的取舍点，材料未给出该比例，但账本结构说明它是首要调参对象。</p>\n<p>压缩还有第二级：全注意力层的 KV 本身也以低精度存放。材料提到 KV 按 4-bit 或更低精度压缩，这意味着 $p_{kv}$ 从 2 字节降到 0.5 字节甚至更低，KV 账户直接缩到四分之一。代价是每次注意力计算前要做 KV 反量化，这和权重反量化一样，把压力从容量转移到带宽与指令吞吐。Fermi 上没有原生低精度路径，KV 反量化的指令开销会叠加在注意力的 softmax 与加权求和上，成为解码循环里的固定税。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-21\">二十一 · 分页、复用与卸载：把账本做成可调度结构</h3>\n<p>账本算清楚只是第一步，真正让 6GB 跑起来的是把三个账户做成可调度结构。分页解决的是 KV 的碎片问题：按固定 token 块（page）分配 KV，而不是按请求整段预留，这样不同长度的请求可以交错共享物理页，长请求不会因为预留整段而挤死短请求。分页的代价是页表查找与块边界处理，在手写内核里意味着额外的索引计算和分支，Fermi 的指令吞吐本就不宽裕，页表开销必须压到每个 token 几次整数运算的量级。</p>\n<p>复用解决的是前缀重复问题。同一系统提示或同一多轮对话前缀在不同请求间重复出现，若每个请求都独立存 KV，等于把同一段 KV 存了多份。前缀共享让相同前缀的 KV 页被多个请求引用，引用计数归零才回收。这在 6GB 上是直接的容量收益：共享一段长前缀，等于把 $b$ 个请求的 KV 账户从 $b\\cdot S$ 降到 $S+(b-1)\\cdot\\Delta S$。代价是引用计数管理与写时复制——一旦某个请求要继续生成不同后缀，共享页必须分叉，分叉点之后的 KV 各自独立。</p>\n<p>卸载解决的是权重与 KV 争抢同一块显存的问题。当活跃专家集扩大或序列变长时，可以把非活跃专家的 4-bit 权重换出到主机内存，把显存让给 KV；反之在批变大、KV 压力上升时，把部分 KV 页换出。卸载的代价是 PCIe 带宽——Fermi 时代的 PCIe 带宽远低于现代 NVLink 5，一次换入换出的延迟可能直接吃掉数个解码步的时间。因此卸载策略必须是“按专家粒度、低频、可预测”的，不能做成每 token 都触发的抖动。工程判断上，卸载只应发生在批切换或长序列阶段切换的边界，而不是解码循环内部。</p>\n<p>一个具体例子：假设剩余显存为 1.5GB，KV 每 token 每层占 0.5KB（4-bit 压缩后），全注意力层占混合层的一半。若批大小为 4、序列长 2048，KV 占用约为 4×2048×0.5KB×层数×0.5，层数未知但账本可算；一旦这个乘积逼近 1.5GB，就必须触发分页回收或降低批大小。这就是为什么材料说“批大小受显存与内核占用约束”——它不是调出来的，是算出来的。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-22\">二十二 · 带宽瓶颈在哪：反量化税与分组 GEMM 的读放大</h3>\n<p>Fermi 上算力不是主要矛盾，带宽才是。4-bit 权重存放把容量问题解决了，但每次 GEMM 都要把打包权重读进来再反量化，读的是 0.5 字节/参数，算的是更高精度的乘加。理论带宽下界是：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\ge \\frac{M_{\\text{read}}}{BW_{\\text{eff}}},\\quad M_{\\text{read}}=k\\cdot M_{e}+M_{\\text{act}}+M_{KV,\\text{read}}$$</div>\n<p>其中 $M_{\\text{read}}$ 是单步解码需要从显存搬进片上的总字节，$BW_{\\text{eff}}$ 是有效带宽（扣除反量化指令挤占后的实际可用带宽）。这个式子的工程含义是：解码一步的时间下限由“搬多少”决定，而不是由“算多少”决定。分组 GEMM 按专家聚合 token，每个专家权重只读一次、服务该专家的所有 token，这降低了权重的读放大；但 token 重排本身要读写索引与激活，路由结果的散射-聚集又是一次显存往返。读放大的来源有三处：权重按专家重复读、激活按 token 块重复读、KV 按头重复读。</p>\n<p>反量化税是第二层带宽代价。4-bit 解包成更高精度需要在寄存器/共享内存里做移位、掩码、缩放，这些指令不产生浮点吞吐，却占用指令发射槽。Fermi 的 SM 没有现代张量核心的异步流水，反量化与 GEMM 只能串行或半重叠，于是有效带宽 $BW_{\\text{eff}}$ 低于标称带宽。这就是材料所说“算力受显存带宽与反量化指令开销双重限制”的具体机制：不是算不动，是搬不动且解包慢。</p>\n<p>对比 Blackwell 的视角：B200 上的 NVFP4 有硬件反量化路径，tcgen05 的 TMEM 让权重与激活的搬运和 MMA 重叠，2-SM MMA 把两个 SM 的算力合并以减少权重重复读。同样的 4-bit 权重，在 Fermi 上是“搬进来再解”，在 Blackwell 上是“搬进来即算”，带宽账本的系数完全不同。这也是为什么该工作的工程价值在极端约束下成立，但不能直接迁移到现代部署。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-23\">二十三 · 可复算的显存预算：把 6GB 拆成四块</h3>\n<p>下面给出一个可复算的预算模板，所有符号都是账本项，填入任一架构参数即可验算是否溢出。它不依赖材料未给出的具体数字，只依赖账本结构。</p>\n<table class=\"mini\">\n<thead><tr><th>账户</th><th>组成</th><th>缩放律</th><th>工程代价</th></tr></thead>\n<tbody>\n<tr><td>权重常驻</td><td>共享层 + k 个活跃专家（4-bit）</td><td>与 k 线性，与专家数无关</td><td>k 越大，KV 余量越小</td></tr>\n<tr><td>权重暂存</td><td>换入缓冲</td><td>常数，按专家粒度</td><td>PCIe 换入延迟</td></tr>\n<tr><td>激活</td><td>token 块 × 隐藏维度 × 精度</td><td>与批大小线性</td><td>批大小上限的直接约束</td></tr>\n<tr><td>KV</td><td>全注意力压缩 KV + 线性状态</td><td>与 S×b 双线性 + 常数项</td><td>反量化税、分页开销</td></tr>\n</tbody>\n</table>\n<p>复算步骤：先定 $k$ 与 $M_e$，得到权重常驻；再从 6GB 减去权重常驻与暂存，得到可用余量 $M_{\\text{avail}}$；然后令激活与 KV 之和不超过 $M_{\\text{avail}}$，解出允许的 $(S,b)$ 组合。这个不等式是：</p>\n<div class=\"formula\">$$M_{\\text{act}}(b)+M_{KV}(S,b)\\le M_{\\text{avail}}=6\\text{GB}-M_{W}$$</div>\n<p>它的解集是一条下降曲线：$S$ 越长，$b$ 越小；$b$ 越大，$S$ 越短。混合注意力的作用就是把这条曲线的斜率变缓——线性注意力层的常数项不随 $S$ 增长，等于把曲线的一部分压平。工程判断上，这条曲线就是容量规划的输入：给定目标上下文长度，反解出最大批大小；给定目标并发，反解出最大上下文。材料没有给出具体吞吐，但这条曲线本身是可复算的，也是这套实现“能跑但跑不快”的定量解释。</p>\n<p>一个具体例子：若 $M_W$ 占去 4GB，$M_{\\text{avail}}$ 只剩 2GB；若激活每请求占 50MB，KV 每请求每千 token 占 100MB，则 4 个请求、2K 上下文就要 4×50MB+4×200MB=1GB，余 1GB 可留给分页与暂存。若把上下文拉到 8K，KV 变成 4×800MB=3.2GB，直接溢出，必须把批降到 2 或启用卸载。这个算术不需要任何未给出的架构参数，就能说明 6GB 的边界在哪。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-24\">二十四 · HBM3e 容量怎么算：Blackwell 上的同一本账</h3>\n<p>把同一本账搬到 Blackwell 上，结构不变，系数全变。B200 的 HBM3e 容量以百 GB 计，35B 模型即使不做 4-bit 也能整模驻留，4-bit 只是把余量进一步放大给 KV 与批。容量账本变为：</p>\n<div class=\"formula\">$$M_{\\text{avail}}^{\\text{Blackwell}}=C_{\\text{HBM}}-M_{W}-M_{\\text{workspace}}-M_{\\text{comm}}$$</div>\n<p>其中 $C_{\\text{HBM}}$ 是单卡 HBM3e 容量，$M_{\\text{workspace}}$ 是框架与内核工作区，$M_{\\text{comm}}$ 是分离式预填/解码与并行通信的缓冲。Blackwell 上 KV 账本的主导项不再是容量，而是带宽：HBM3e 带宽远高于 Fermi 的显存带宽，KV 读写不再是瓶颈，反量化税被 NVFP4 硬件路径吸收，账本的重心从“装不装得下”转到“搬得够不够快”。这就是同一本账在两个时代的读法差异——Fermi 上权重账户是硬约束，Blackwell 上 KV 与通信缓冲才是需要精算的部分。</p>\n<p>工程判断落在具体机制上：在 Fermi 上，混合注意力的比例、KV 压缩精度、专家换入粒度三者共同决定 $(S,b)$ 解集；在 Blackwell 上，同一组参数要让位于 NVFP4 的缩放因子布局、TMEM 的占用与 2-SM MMA 的配对约束。账本方法可复用，但每一项的系数必须按目标硬件的带宽与容量重填，不能把 6GB 上的取舍直接当成现代部署的配方。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-25\">二十五 · 连续批处理在 6GB 预算下的可行边界</h3>\n<p>连续批处理（continuous batching）的核心是把“批”从请求级下沉到迭代级：每一步解码只对当前活跃序列集合做一次前向，序列完成即出队、新请求随即入队，从而避免静态批中短请求等待长请求造成的槽位空转。在 Blackwell 上这套机制由调度器与分页 KV 管理器共同支撑，代价主要是 KV 块表的间接寻址与每步重组的 host 侧开销。把这套机制搬到 6GB Fermi 上，第一道硬约束不是调度算法，而是 KV 预算：权重已按 4-bit 打包占据显存主体，留给 KV 的空间被压缩到极窄，活跃序列数上限由“每 token 每层 KV 字节数 × 序列长度 × 层数”直接决定，而不是由算力决定。</p>\n<p>设活跃序列集合为 <span>S</span>，序列 <span>i</span> 的当前长度为 <span>L_i</span>，全注意力层数为 <span>N_full</span>，每 token 每层 KV 压缩后字节数为 <span>b</span>，则 KV 占用可写为：</p>\n<div class=\"formula\">$$M_{KV}=\\sum_{i\\in S} L_i \\cdot N_{full} \\cdot b + M_{state}$$</div>\n<p>其中 <span>M_state</span> 是线性注意力层常数级状态的固定开销，与序列长度无关——这正是混合注意力结构对调度的直接馈赠：线性层不随 <span>L_i</span> 增长，调度器只需为全注意力层做预算。工程判断是：在 6GB 上，连续批处理的“批大小”实际上是 KV 预算除以平均序列长度的商，调度器的第一职责是拒绝超出预算的入队，而不是追求更大并发。代价体现在两个方向：入队过松会触发显存不足，入队过紧则 GPU 在解码步上空转，尾延迟与吞吐同时受损。</p>\n<p>具体例子：若某步活跃集合为三条序列，长度分别为 512、1024、2048，全注意力层每 token 每层压缩 KV 为若干字节量级，则长序列单独就吃掉预算的绝大部分；此时把第四条长请求放进同一批，只会让整批在下一步因预算越界而被迫驱逐，驱逐又带来重算成本。可行做法是给调度器加一条“长度分档”规则：短序列与长序列分池，短池追求高并发填满解码步，长池只保留单条或极少条序列，用 chunked prefill 摊平首 token 成本。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-26\">二十六 · Chunked prefill：把首 token 的尖峰切成台阶</h3>\n<p>Chunked prefill 把一条长 prompt 的预填拆成若干固定 token 数的块，与正在解码的序列混在同一批里逐步推进。它的直接收益是消除“预填独占 GPU”造成的解码停顿，把首 token 延迟（TTFT）从一次长尖峰变成若干次短台阶；代价是预填块与解码 token 共享同一次前向的算力与带宽，解码步的间隔被拉长，token 间延迟（ITL）出现周期性抖动。在 Fermi 上这一取舍被放大：没有张量核心，预填阶段的 GEMM 与解码阶段的 GEMV 都受显存带宽与反量化指令吞吐约束，块大小选大了会挤占解码，选小了则预填吞吐塌陷。</p>\n<p>块大小的选择可用一个粗略的平衡式表达：设单步预算时间为 <span>T_step</span>，解码 token 数为 <span>n_d</span>，每 token 解码耗时 <span>t_d</span>，预填块含 <span>n_p</span> 个 token，每 token 预填耗时 <span>t_p</span>，则要求</p>\n<div class=\"formula\">$$n_d\\cdot t_d + n_p\\cdot t_p \\le T_{step},\\quad \\text{且}\\ n_p\\cdot t_p\\ \\text{不使 ITL 超出 SLO}$$</div>\n<p>由于 <span>t_p</span> 与 <span>t_d</span> 都由反量化与分组 GEMM 的带宽开销主导，二者的比值相对稳定，块大小实际上由 ITL 的容忍度反推。工程上更稳的做法是把预填块做成“可抢占单元”：块推进到一半若检测到解码队列积压，就在块边界让出，下一轮再续，这样 ITL 的上界由单块时长决定而非整条 prompt 长度决定。</p>\n<p>具体例子：一条数千 token 的 prompt 若一次性预填，解码队列在这段时间内完全停摆，尾延迟由这条请求的长度直接决定；切成固定小块后，每个解码步只多承担一块预填的带宽开销，长 prompt 的首 token 被摊到多个步上，代价是这条请求自身的 TTFT 变长。对 6GB 单卡而言，这是唯一能在不驱逐解码序列的前提下容纳长 prompt 的手段。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-27\">二十七 · 优先级与抢占：驱逐谁、重算多少</h3>\n<p>优先级调度在容量极紧的机器上不是可选项而是必需品：当 KV 预算不足以同时容纳高优先级新请求与低优先级在途序列时，调度器必须驱逐（preempt）部分序列。驱逐策略分两类：交换（swap）把 KV 块换出到 host 内存，恢复时换回，代价是 PCIe 往返带宽；重算（recompute）直接丢弃 KV，恢复时把已生成 token 重新预填一遍，代价是重复的预填算力。在 Fermi 这类老卡上，PCIe 带宽相对显存带宽更显稀缺，且 host 侧内存拷贝会打断解码流水，因此重算往往比交换更可控——前提是被驱逐序列的长度不长，重算量有界。</p>\n<p>设被驱逐序列长度为 <span>L</span>，重算预填每 token 成本为 <span>c_p</span>，交换往返每字节成本为 <span>c_s</span>，KV 每 token 字节数为 <span>b</span>，则两种策略的代价比较为：</p>\n<div class=\"formula\">$$\\text{cost}_{recompute}=L\\cdot c_p,\\qquad \\text{cost}_{swap}=2L\\cdot b\\cdot c_s$$</div>\n<p>当 <span>L</span> 较大时交换占优，当 <span>L</span> 较小时重算占优；但由于 <span>c_p</span> 在无张量核心的卡上被反量化开销抬高，交点会向“更倾向交换”的方向移动，而 PCIe 的实际有效带宽又把这个交点拉回。工程判断是：给驱逐设一个长度阈值，短序列重算、长序列交换，并在驱逐时优先选择“已生成 token 多但剩余生成长度短”的序列，因为它们的重算收益最低、释放的 KV 最多。</p>\n<p>具体例子：一条已生成数十 token、预计还要生成数百 token 的低优先级请求，其 KV 占用随长度线性增长，继续保留会持续挤压高优先级请求的入队空间；驱逐它并重算已生成部分，代价是一次短预填，换来的是高优先级请求的 TTFT 不被推迟。反过来，一条刚入队、长度很短的请求被驱逐几乎无收益，因为释放的 KV 太少，调度器应避免这种“抖动式驱逐”。抢占的另一个隐性代价是分组 GEMM 的批形状被打散：被驱逐序列退出后，按专家分组的 token 块变小，反量化内核的固定开销占比上升，单步有效吞吐下降。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-28\">二十八 · 分离式预填/解码在单卡上的退化形态</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）在 Blackwell 集群上把预填与解码拆到不同节点，用 NIXL 之类的传输层搬运 KV，目的是让两类负载各自跑在最适合的并行形态上，互不干扰 ITL。在单张 6GB Fermi 上，这一机制退化为“时间上的分离”而非“空间上的分离”：同一张卡在不同时间片分别承担预填与解码，KV 不跨设备搬运，而是留在原地由调度器切换角色。这样做保住了“预填不打断解码”的初衷，却失去了分离式部署最核心的收益——预填与解码的算力不再能并行重叠。</p>\n<p>退化形态的代价可以直接写成时间占比：设一个调度周期内预填时间为 <span>T_p</span>、解码时间为 <span>T_d</span>，则解码吞吐的相对损失为</p>\n<div class=\"formula\">$$\\eta=\\frac{T_d}{T_p+T_d}$$</div>\n<p>由于预填的 GEMM 在无张量核心的卡上被反量化指令开销主导，<span>T_p</span> 的占比不低，<span>η</span> 会被明显压低。可行的缓解是把预填切片嵌入解码步（即上一节的 chunked prefill），使 <span>T_p</span> 不再是一整段独占时间，而是分散的小块——这实际上是把“分离”做成了“交织”，用 ITL 的轻微抖动换取解码队列不停摆。</p>\n<p>具体例子：若调度器按“先攒一批预填、再放开解码”的粗粒度切换，解码序列在每个周期开头都要空等整段预填，尾延迟呈锯齿状；改为每步夹带一小块预填后，锯齿被削平，代价是每步时长略增。对 6GB 单卡，交织式是唯一能同时满足“长 prompt 可入队”和“解码不长时间停摆”的形态；真正的分离式部署需要多卡与高速互联，而该实现明确不涉及专家并行与 All-to-All，通信开销为零但容量成为唯一瓶颈。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-29\">二十九 · 尾延迟怎么压：从 P99 反推调度参数</h3>\n<p>尾延迟的来源在 6GB 机器上高度集中：一是长 prompt 的预填尖峰，二是驱逐引发的重算，三是分组 GEMM 的负载不均——路由把 token 集中到少数热点专家时，按专家分组的 token 块大小悬殊，最慢的那一块决定整步时长。前两者靠 chunked prefill 与驱逐阈值控制，第三者靠容量因子（capacity factor）与 token 丢弃策略控制，但在专家权重全部驻留本地、无 All-to-All 的单卡形态下，负载不均无法靠跨卡迁移摊平，只能靠调度侧限制单步内进入热点专家的 token 数。</p>\n<p>把 P99 作为约束反推参数，可以写成：设单步时长分布的第 99 百分位为 <span>T_{99}</span>，它由最长预填块、最大专家块与解码 token 数共同决定，则调度器应满足</p>\n<div class=\"formula\">$$T_{99}=\\max\\left(n_p^{max}\\cdot t_p,\\ \\max_{e}\\ n_e\\cdot t_e\\right)+n_d\\cdot t_d \\le T_{SLO}$$</div>\n<p>其中 <span>n_e</span> 是单步内路由到专家 <span>e</span> 的 token 数，<span>t_e</span> 是该专家分组 GEMM 的单位 token 成本。这个式子说明：压尾延迟不是压平均值，而是压“最慢的那一块”。工程手段有三条——限制单块预填的 token 上限、对热点专家设 token 上限并在超出时把多余 token 推迟到下一步、以及在驱逐时优先选那些不会造成专家块形状突变的序列。</p>\n<p>具体例子：某步路由后某专家聚集了大量 token，其分组 GEMM 成为整步瓶颈，其他专家的内核早早空闲等待；此时若调度器在路由后插入一次“块大小检查”，把超出上限的 token 延后一步，单步时长被削平，代价是这些 token 的产出晚一步。对逐 token 解码的请求流，晚一步意味着 ITL 增加一个步长，但 P99 不再由偶发的专家热点决定。这类控制与连续批处理的入队规则耦合：入队时若预估新请求会显著加剧专家热点，就应推迟入队而非硬塞。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-30\">三十 · 时延与吞吐的取舍落点</h3>\n<p>在 6GB Fermi 上，吞吐与时延不是一条平滑的帕累托前沿，而是被显存预算切成几段：预算内提高并发能提升吞吐但拉长 ITL，越过预算则触发驱逐、重算与专家块抖动，吞吐反而塌陷。因此调度器的目标不是“最大化批大小”，而是“把批大小稳定在预算内的拐点附近”。这个拐点由 KV 预算、单步预算时间与专家块上限三者共同界定，任何一项越界都会把系统推入尾延迟陡增的区间。</p>\n<p>把三者写成约束组，调度问题可表述为：在 <span>M_KV ≤ M_budget</span>、<span>T_step ≤ T_SLO</span>、<span>n_e ≤ n_e^{max}</span> 下最大化单步有效 token 产出。这是一个带硬约束的装箱问题，实时求解不现实，工程上退化为几条启发式：按长度分池、按优先级驱逐、按块上限切片、按专家热点限流。每条启发式都对应一个明确的系统代价——分池降低短池的批填充率，驱逐带来重算，切片拉长 TTFT，限流推迟 token 产出——调度参数的选择本质上是在这些代价之间分配预算。</p>\n<p>具体判断：当负载以短请求为主时，优先保吞吐，放宽专家块上限、缩小预填块，让解码步尽量填满；当负载混入长 prompt 或高优先级请求时，优先保尾延迟，收紧块上限、启用长度分池、把驱逐阈值下调。该实现的材料未给出吞吐与延迟数字，因此这些参数只能定性设定，无法用实测拐点校准——这正是极端旧硬件部署的工程现实：调度策略的正确性依赖对瓶颈的定性判断，而非可复现的性能曲线。真正可迁移到 Blackwell 的部分不是这些具体阈值，而是“先由 KV 预算定并发上限、再由单步预算定块大小、最后由专家块形状定尾延迟”的推导顺序。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-31\">三十一 · 单卡零通信的基线：为什么这篇论文的并行章节从“不可用”写起</h3>\n<p>这篇论文的部署前提决定了并行与通信这一章不能按常规写法展开：模型是 35B 级混合注意力 MoE，硬件是 2011 年 Fermi 架构、6GB 显存的单卡。材料明确说明该实现不涉及专家并行与 All-to-All，专家权重全部驻留本地显存，通信开销为零，容量是唯一瓶颈。因此本部分的价值不在于复述 TP/EP/PP/DP 的定义，而在于把这套单卡实现当作一个“通信项恒为零”的极端参照点，反过来标定 Blackwell 上通信何时从可忽略变为瓶颈。换言之，Fermi 版本给出的是并行切分的下界情形：当模型放不进一张卡时，切分是唯一出路；当模型勉强塞进一张卡时，切分带来的每一字节通信都是净成本。</p>\n<p>先把四种切分的语义压缩成一句话指路：TP 切分单层内的权重矩阵，每层前后各需一次集合通信；EP 切分专家，路由后需要 All-to-All 把 token 送到专家所在设备；PP 切分层，只在阶段边界传激活；DP 复制整模型、切分请求，只在梯度场景需要通信，推理侧通常零通信。这篇论文的单卡形态等价于 TP=1、EP=1、PP=1、DP=1，所有集合通信算子退化为本地内存拷贝。它的工程意义在于：4-bit 打包权重把 35B 压进 6GB 之后，容量约束被满足，代价是算力被反量化指令与显存带宽双重限制，而这一代价无法通过增加设备分摊——因为 Fermi 没有 NVLink，多卡互联只能走 PCIe，任何跨卡张量交换的带宽都远低于片内。</p>\n<p>用公式刻画这个参照点的代价结构。单卡逐 token 解码时，每步的时间下界由权重读取带宽决定：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\ge \\frac{W_{\\text{active}}}{B_{\\text{HBM}}} + T_{\\text{dequant}},\\quad W_{\\text{active}} = \\sum_{e\\in\\text{TopK}} \\frac{1}{4}\\cdot|\\hat{W}_e|$$</div>\n<p>其中 $W_{\\text{active}}$ 是当步被路由激活的专家权重字节数（4-bit 即每参数半字节），$B_{\\text{HBM}}$ 是显存带宽，$T_{\\text{dequant}}$ 是手写反量化内核的指令开销。这个式子说明：在单卡上，通信项不存在，瓶颈完全落在带宽与指令吞吐上；一旦引入 EP，分子不变（激活专家总量不变），但分母变成“本地带宽 + 跨卡带宽的调和平均”，并且多出一个与 token 数成正比的 All-to-All 项。Blackwell 的 NVLink 5 把这个跨卡项抬高了整整一个量级，但抬高不等于消失——这正是后文要定量判断的地方。</p>\n<p>具体例子：假设某层路由把一批 token 分给 8 个专家，单卡时这 8 个专家的 4-bit 权重按分组 GEMM 顺序加载，反量化在寄存器/共享内存完成，token 块在本地重排，没有任何跨设备索引。若把这 8 个专家分到 8 张卡（EP=8），每个 token 的 top-k 结果需要先做一次 All-to-All 把 token 送到目标卡，算完再 All-to-All 送回，重排从本地共享内存操作变成跨卡 DMA。Fermi 上这一步走 PCIe，其带宽与延迟使 EP 完全不划算；而在 GB200 NVL72 上，同样一步走 NVLink 5 与 NVSwitch，单跳带宽与聚合带宽都足以让 EP 成为常规选项。同一个算法结构，在两个时代的代价相差的不是常数倍，而是“可用/不可用”的定性差别。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-32\">三十二 · TP 的通信账：每层两次集合通信与激活的临界尺寸</h3>\n<p>TP 的机制是把一个权重矩阵按列或按行切开，每张卡只持有 $1/N$ 的权重，但每层前向需要把部分和汇聚。典型的行并行线性层后接一次 All-Reduce，列并行线性层前接一次 All-Reduce（或等价地用 reduce-scatter + all-gather 融合）。于是每层的通信量与激活张量成正比，与权重无关：</p>\n<div class=\"formula\">$$V_{\\text{TP}} = 2\\cdot b\\cdot s\\cdot h\\cdot \\frac{N-1}{N}\\cdot \\text{sizeof(dtype)}$$</div>\n<p>其中 $b$ 是批大小，$s$ 是序列长度（解码时为 1），$h$ 是隐藏维度，$N$ 是 TP 度。这个式子的关键含义是：TP 的通信量随批大小线性增长，而计算量也随批大小线性增长，所以 TP 在解码阶段的“通信/计算比”是一个与批大小无关的常数——这意味着增大批并不能摊薄 TP 通信，只能靠提高单卡算力或降低通信延迟来改善。这正是 TP 在小批解码时最容易成为瓶颈的原因：矩阵乘是瘦长的（$b\\cdot s$ 很小），算术强度低，集合通信的固定延迟占比高。</p>\n<p>在 Blackwell 上，TP 的通信由 NVLink 5 与 NVSwitch 承载，机柜内全互联使 All-Reduce 可以走硬件多播路径，延迟远低于 PCIe 时代的环形归约。但代价仍然存在：All-Reduce 的带宽消耗是双向的，且在多租户 NVL72 中与 EP 的 All-to-All 争抢同一批链路。工程判断是：TP 度超过单机 8 卡后，跨 NVLink 域的 All-Reduce 延迟开始进入关键路径，此时应优先考虑用 PP 或 EP 替代更高的 TP，而不是继续加 TP 度。</p>\n<p>具体例子：一个 35B 级 MoE 若以 BF16 部署，单层隐藏维度按材料未给出的架构参数无法精确计算，但可以定性说明——TP=8 时每层两次 All-Reduce 的激活量级在百 KB 到 MB 之间，解码批大小为 1 时单次 All-Reduce 的延迟主导该层时间；而在预填阶段序列长度上千，通信量放大三个数量级，All-Reduce 带宽成为主导。这解释了为什么分离式预填/解码（PD 分离）在 Blackwell 上成为常规架构：预填阶段用高 TP 度换带宽，解码阶段用低 TP 度换延迟，两个阶段的并行拓扑不必相同。该论文的单卡实现没有这个自由度，因为 TP=1 时预填与解码共享同一份本地权重，通信项恒为零，代价全部体现为预填阶段的反量化指令洪流。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-33\">三十三 · EP 与 All-to-All：MoE 推理的通信主战场</h3>\n<p>EP 是 MoE 推理中最具代表性的并行形态，也是通信最容易成为瓶颈的地方。机制是：每个 token 经路由选出 top-k 专家，专家分布在不同设备上，因此需要一次 All-to-All 把 token 的激活发送到专家所在设备，专家计算完成后再一次 All-to-All 把结果送回原设备并按路由权重加权。通信量与路由结果直接相关：</p>\n<div class=\"formula\">$$V_{\\text{EP}} = 2\\cdot b\\cdot s\\cdot k\\cdot h\\cdot \\text{sizeof(dtype)}\\cdot \\frac{N-1}{N}$$</div>\n<p>与 TP 的式子对比可以看出关键差别：EP 的通信量多了一个因子 $k$（top-k），并且发送的是“被选中的 token 副本”，而不是完整激活。这意味着 EP 通信量对路由分布的偏斜极其敏感——如果某些专家成为热点，对应设备的入站流量会集中，All-to-All 的完成时间由最慢的那条链路决定，而不是平均带宽。这就是 MoE 推理中“负载不均放大通信代价”的机制：算术上总通信量不变，但时间上被最热专家的队列长度支配。</p>\n<p>Blackwell 的 NVLink 5 与 NVSwitch 把 All-to-All 的物理层从“多跳环形”变成“单跳全互联”，NVL72 域内 72 张 GPU 两两之间都是一跳，这使得 All-to-All 的延迟不再随 EP 度线性增长，而是接近常数加带宽项。但代价转移到另外两处：一是 NVSwitch 的聚合带宽是共享资源，EP 的 All-to-All 与 TP 的 All-Reduce、KV 传输、NIXL 的跨节点搬运争抢同一批链路；二是 All-to-All 的软件栈开销（索引构造、缓冲区管理、NCCL 或自定义通信器的启动延迟）在小消息时占比高。工程判断是：EP 度在单机 8 卡内时，All-to-All 通常被 NVLink 5 完全吸收，瓶颈回到专家计算的算术强度；跨机柜扩展到 NVL72 全域时，All-to-All 的尾延迟与链路争用开始进入 SLO 预算。</p>\n<p>具体例子：该论文的单卡实现把 EP 退化为 EP=1，路由后的 token 重排完全在本地完成——按专家分组的 token 块在共享内存中聚合，分组 GEMM 逐专家加载 4-bit 权重。这个过程的“通信”成本为零，但重排本身的索引构造与 token 搬运仍然是显存带宽开销，且由于 6GB 显存无法容纳大 batch，重排的固定开销无法被摊薄。把同一结构搬到 EP=8 的 Blackwell 节点上，重排从本地共享内存操作变成 All-to-All 的发送/接收缓冲，索引构造从本地循环变成跨卡元数据交换；若 top-k 较大且专家数较多，元数据交换的延迟可能超过激活传输本身。这就是为什么现代 MoE 推理框架普遍采用“ fused dispatch ”把路由、重排与 All-to-All 合并进一个内核，以减少启动次数与中间缓冲。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-34\">三十四 · PP 与 DP：边界传输与零通信的两种极端</h3>\n<p>PP 的机制是按层切分，每个阶段持有连续若干层，阶段之间只传激活，不传权重。通信量是：</p>\n<div class=\"formula\">$$V_{\\text{PP}} = b\\cdot s\\cdot h\\cdot \\text{sizeof(dtype)}$$</div>\n<p>注意这里没有 $N$ 因子，因为 PP 的通信只发生在阶段边界，与 PP 度无关（每个边界一次）。PP 的代价不在带宽而在流水线气泡：解码阶段每步只处理一个 token，阶段间必须串行等待，气泡占比接近 $(N-1)/N$，除非用交错微批或多请求并发填充。因此 PP 在推理中通常用于“模型大到单卡放不下、且并发足够高”的场景，而不是低延迟单请求场景。Blackwell 上 PP 的边界传输走 NVLink 5，带宽充足，真正的约束是流水线调度与 KV cache 的分段放置——每个阶段只持有自己那几层的 KV，跨阶段访问需要显式搬运，这与 PD 分离的 KV 传输共享同一套 NIXL 通路。</p>\n<p>DP 在推理侧是最省事的切分：每个副本持有完整模型，请求按路由分发到副本，副本之间零通信。代价是显存：每个副本都要放一份完整权重与一份 KV 预算，因此 DP 度受单卡显存上限约束。对 35B 级 MoE 而言，DP 的前提是权重已经压到单卡可容纳——这正是该论文 4-bit 打包的意义：把 35B 压进 6GB 之后，DP=1 就是唯一可行的拓扑，任何增加副本的想法都被显存否决。反过来在 Blackwell 上，NVFP4 让 35B 级模型的权重占用进一步下降，单卡可容纳的副本数增加，DP 成为提升吞吐的首选手段，因为它的通信成本为零、调度最简单。</p>\n<p>具体例子：一个 GB200 NVL72 机柜内，若把 35B MoE 以 NVFP4 部署，单卡权重占用允许每卡放多个副本，DP 度可以按请求并发数线性扩展，副本间无需任何集合通信；而若改用 EP=72 的全域专家并行，每步解码都要一次全域 All-to-All，虽然 NVSwitch 能吸收带宽，但尾延迟与链路争用使低延迟 SLO 难以满足。工程判断因此是：解码阶段优先 DP + 低 TP，预填阶段优先高 TP + EP，两者用 PD 分离解耦——这与该论文单卡形态下“预填与解码共享同一拓扑、通信恒为零但吞吐受限”形成鲜明对照。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-35\">三十五 · NIXL 与跨节点传输：当通信走出 NVLink 域</h3>\n<p>NIXL 解决的是 NVLink 域之外的传输问题：PD 分离后预填节点与解码节点可能不在同一机柜，KV cache 需要跨节点搬运；EP 扩展到多机柜时，All-to-All 需要跨 InfiniBand 或以太网。NIXL 的机制是提供一个统一的传输抽象，把显存到显存的搬运分解为注册内存、描述符交换与异步传输，底层可走 RDMA、NVLink 或本地拷贝，上层框架（Dynamo、TensorRT-LLM、vLLM）只需声明“把这段 KV 从 A 传到 B”。其代价结构是：</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = T_{\\text{setup}} + \\frac{V_{\\text{KV}}}{B_{\\text{link}}},\\quad V_{\\text{KV}} = 2\\cdot L\\cdot h_{\\text{kv}}\\cdot s\\cdot \\text{sizeof(dtype)}$$</div>\n<p>其中 $T_{\\text{setup}}$ 是描述符交换与连接建立的固定开销，$V_{\\text{KV}}$ 是 KV 字节数（因子 2 对应 K 与 V），$L$ 是层数。这个式子说明：跨节点 KV 传输的可行性取决于 $V_{\\text{KV}}/B_{\\text{link}}$ 是否小于预填与解码的时间差——如果传输时间超过预填节省的时间，PD 分离就失去意义。混合注意力结构在这里有直接价值：线性注意力层以常数级状态替代增长型 KV，只有全注意力层需要搬运压缩后的 KV，$L$ 的有效值下降，$V_{\\text{KV}}$ 随之下降。该论文用混合注意力把 KV 压进 6GB，这个机制在 Blackwell 的 PD 分离场景下转化为跨节点传输量的削减，是同一设计在两个时代的复用。</p>\n<p>具体例子：一个长上下文请求在预填节点完成全注意力层的 KV 计算后，需要把压缩 KV 传给解码节点。若 $V_{\\text{KV}}$ 在百 MB 量级，NVLink 域内传输在毫秒级，跨 InfiniBand 则在十毫秒级；后者对首 token 延迟敏感的场景不可接受，因此 PD 分离通常要求预填与解码在同一 NVL72 域内，或至少共享高带宽互联。NIXL 的价值在于把这条路径的选择权交给调度器：同域走 NVLink，跨域走 RDMA，传输语义一致，框架无需为两种路径写两套代码。代价是 $T_{\\text{setup}}$ 在小 KV 时占比高，因此短请求不适合 PD 分离，长请求才摊薄固定开销。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-36\">三十六 · 通信何时成为瓶颈：一个可操作的判据</h3>\n<p>把前五节的式子合并成一个判据：某并行维度的通信时间与计算时间之比超过阈值时，该维度就成为瓶颈。对 TP 与 EP，通信/计算比可以写成：</p>\n<div class=\"formula\">$$\\rho = \\frac{V_{\\text{comm}}/B_{\\text{link}}}{F_{\\text{layer}}/P_{\\text{peak}}}$$</div>\n<p>其中 $F_{\\text{layer}}$ 是该层浮点运算量，$P_{\\text{peak}}$ 是单卡峰值算力。$\\rho$ 的分母在 Blackwell 上因 tcgen05 与 NVFP4 而大幅提升，分子因 NVLink 5 而下降，所以 $\\rho$ 整体下降——但这不意味着通信永远不是瓶颈，因为 $V_{\\text{comm}}$ 在解码阶段不随批大小缩小，而 $F_{\\text{layer}}$ 随批大小线性缩小，于是小批解码时 $\\rho$ 反而上升。这就是“通信在解码阶段比预填阶段更容易成为瓶颈”的定量解释，也是 PD 分离要按阶段配置不同并行拓扑的根本原因。</p>\n<p>可操作的判据分三层。第一层看拓扑：TP 度超过单机 NVLink 域、EP 度跨机柜、PP 阶段数超过并发微批数，三者任一成立时通信进入关键路径。第二层看消息尺寸：All-Reduce 与 All-to-All 的消息小于链路延迟带宽积时，固定延迟主导，此时应合并通信（fused dispatch、reduce-scatter 融合）而不是加带宽。第三层看争用：同一 NVL72 域内同时跑 TP 的 All-Reduce、EP 的 All-to-All 与 NIXL 的 KV 传输时，NVSwitch 聚合带宽被三方瓜分，任何一方的尾延迟都会抬升；工程上应把 PD 分离的 KV 传输与 EP 的 All-to-All 在时间上错开，或为 KV 传输预留独立链路。</p>\n<p>具体例子：该论文的单卡实现中 $\\rho$ 恒为零，因为 $V_{\\text{comm}}=0$；它的瓶颈完全落在 $T_{\\text{dequant}}$ 与 $W_{\\text{active}}/B_{\\text{HBM}}$ 上。把这个实现作为参照，Blackwell 上的工程判断是：当模型能被 NVFP4 压进单卡时，优先 DP 而非 TP/EP，因为 DP 的 $\\rho=0$；当模型必须切分时，优先把通信密集的 EP 放在 NVLink 域内、把 PP 的边界放在域边界、把 KV 传输交给 NIXL 并按请求长度决定是否跨域。通信不是越少越好，而是要让 $\\rho$ 在每一个 SLO 关键路径上都低于阈值——这个判断与硬件代际无关，只与消息尺寸、链路带宽与算力峰值三者的比例有关。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-37\">三十七 · 精度塌陷：4-bit 反量化的误差放大路径</h3>\n<p>在这套实现里，精度塌陷不是“模型变笨”这种笼统描述，而是一条可以逐层追踪的误差放大链。权重以 4-bit 打包存放，计算前在寄存器/共享内存中反量化为更高精度，反量化公式为 <span class=\"formula\">$$\\hat{W}=s\\cdot\\mathrm{dequant}_{4}(W_{q})$$</span>，其中尺度 <span class=\"formula\">$$s$$</span> 是分组量化尺度。Fermi 没有原生低精度路径，因此反量化完全由手写内核完成，误差来源有三处：一是 4-bit 码本本身的量化台阶，二是尺度 <span class=\"formula\">$$s$$</span> 的选取粒度（分组越粗，组内动态范围被压缩得越厉害），三是反量化后与激活相乘时的累加精度。三者叠加在 MoE 结构上会被路由放大：<span class=\"formula\">$$y=\\sum_{e\\in\\mathrm{TopK}(x)}{g_{e}(x)\\cdot \\mathrm{GEMM}(\\hat{W}_{e},x)}$$</span>，一旦某个专家的权重误差偏大，而路由又恰好把大量 token 分给它，误差就沿 <span class=\"formula\">$$g_{e}(x)$$</span> 加权进入残差流，逐层累积。</p>\n<p>诊断这类塌陷的关键是区分“全局性退化”与“专家局部性退化”。全局性退化表现为输出重复、语法崩坏、长序列后半段发散，通常指向反量化尺度整体偏移或累加精度不足；专家局部性退化则表现为特定主题的请求质量骤降而其他主题正常，指向个别专家的 4-bit 权重在分组边界上被截断。工程上可用的定位手段是在解码循环里插入探针：对每一层记录激活的绝对值均值与最大值、记录路由熵（top-k 权重分布的集中程度），当某层激活均值相对基线偏移超过阈值而路由熵同时下降，就基本可以锁定是该层某个专家组的量化尺度问题。代价是探针本身要占用显存与带宽——在 6GB 预算下，探针只能采样而非全量记录，采样率与探针精度直接冲突，这是这套实现里监控与吞吐的固有矛盾。</p>\n<p>具体例子：假设某层路由把 70% 的 token 压给两个专家，而这两个专家的 4-bit 分组尺度恰好覆盖了一个异常大的权重动态范围，组内小权重被量化到零。此时该层输出对这两个专家高度依赖，误差被 <span class=\"formula\">$$g_{e}(x)$$</span> 放大后写入残差，下一层全注意力层的 KV 又被这个偏移污染，形成跨层的连锁塌陷。回滚策略因此不能只回滚量化配置，而要连同路由统计一起回滚——因为路由分布已经因误差而偏移，单纯恢复权重尺度不足以恢复原来的 token 分配。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-38\">三十八 · OOM：6GB 预算下的三类溢出与判定</h3>\n<p>6GB 显存要同时容纳 4-bit 打包权重、反量化临时缓冲、压缩 KV 与激活，任何一项越界都会触发 OOM。这里的 OOM 不是单一故障，而是三种不同性质的溢出，诊断时必须分开。第一类是权重驻留溢出：35B 参数以 4-bit 存放，权重本身占据显存的主体，材料未给出具体字节数，但可以确定权重是预算的最大项，任何额外的权重副本（例如为分组 GEMM 预取的专家块）都会直接挤压剩余空间。第二类是反量化临时缓冲溢出：分组 GEMM 逐专家加载 4-bit 权重后在片内反量化，反量化后的高精度块需要寄存器或共享内存承载，块越大、并行度越高，片内压力越大，溢出表现为内核启动失败或共享内存配置被拒绝。第三类是 KV 溢出：混合注意力下全注意力层保留压缩 KV，线性注意力层以常数级状态替代增长型 cache，但全注意力层的 KV 仍随序列长度增长，长上下文请求会把这部分预算吃穿。</p>\n<p>判定方法依赖一个简单的预算不等式：设权重占用 <span class=\"formula\">$$M_{w}$$</span>、KV 占用 <span class=\"formula\">$$M_{kv}(L)$$</span>（<span class=\"formula\">$$L$$</span> 为序列长度）、激活与临时缓冲 <span class=\"formula\">$$M_{a}$$</span>，则可行条件为 <span class=\"formula\">$$M_{w}+M_{kv}(L)+M_{a}\\le 6\\,\\mathrm{GB}$$</span>。由于 <span class=\"formula\">$$M_{kv}$$</span> 随 <span class=\"formula\">$$L$$</span> 单调增长而 <span class=\"formula\">$$M_{w}$$</span> 固定，存在一个临界序列长度 <span class=\"formula\">$$L^{*}$$</span>，超过它必然 OOM。诊断的第一步不是看报错，而是反推 <span class=\"formula\">$$L^{*}$$</span>：在固定批大小下逐步加长输入，记录首次失败的长度，再与理论预算对照，若实测远小于理论值，说明 <span class=\"formula\">$$M_{a}$$</span> 被低估，通常是反量化缓冲或分组 GEMM 的中间结果没有及时释放。</p>\n<p>系统代价上，OOM 的直接后果是请求失败，但更隐蔽的代价是“为防 OOM 而压低批大小”带来的吞吐损失。批大小受显存与内核占用约束，材料未给出具体上限，但可以确定在 6GB 下批大小极紧，任何为留安全余量而做的保守配置都会成倍削减吞吐。具体例子：若把批大小从可行上限下调一档以规避 KV 峰值，单次解码的 token 数减少，而权重加载与反量化的固定开销不变，单位 token 的带宽成本上升，吞吐下降的幅度大于批大小下降的幅度——这是典型的“安全余量税”。回滚手段因此不是简单调小批，而是按层类型分别限制序列长度：对全注意力层设硬上限，对线性注意力层放开，把 KV 预算集中给真正增长的那部分。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-39\">三十九 · 批抖动：路由负载不均如何传导为时延抖动</h3>\n<p>批抖动指的是相同批大小下，逐 token 解码的步进时间出现大幅波动。在这套实现里，抖动的根源不在批调度本身，而在 MoE 路由的负载分布。分组 GEMM 按专家聚合 token，每个专家的 token 块大小取决于路由结果；当某一批 token 集中路由到少数专家时，这些专家的 GEMM 块变大，而其余专家的块变小甚至为空。Fermi 缺少张量核心，算力受显存带宽与反量化指令开销限制，大块的专家计算时间近似正比于 token 数乘以权重加载量，因此单个专家的膨胀会直接拉长整个步进的关键路径。材料未给出路由负载分布，但明确提示“专家热点可能加剧分组 GEMM 的负载不均”，这正是批抖动的机制来源。</p>\n<p>量化抖动可以用步进时间的变异系数来刻画：设第 <span class=\"formula\">$$t$$</span> 步的耗时为 <span class=\"formula\">$$\\tau_{t}$$</span>，则抖动指标为 <span class=\"formula\">$$\\mathrm{CV}=\\frac{\\mathrm{std}(\\tau_{t})}{\\mathrm{mean}(\\tau_{t})}$$</span>。诊断时不能只看均值，因为均值会被少数极慢步掩盖；应同时记录每步的最大专家块 token 数与专家块数量的分布。若最大块 token 数与均值之比持续偏高，说明路由集中；若专家块数量骤减而总 token 数不变，说明路由坍缩到少数专家。这两种情况的处理不同：前者需要容量因子或路由温度调节来摊平分布，后者则可能是精度塌陷的前兆——路由坍缩往往伴随专家输出退化，二者要联合诊断。</p>\n<p>系统代价方面，批抖动的直接后果是尾延迟抬升（见下一节），间接后果是批调度器难以维持稳定节奏。逐 token 解码循环中，每一步都要等待最慢的专家 GEMM 完成，快专家的算力被浪费，慢专家成为瓶颈。具体例子：一批 token 中 60% 路由到专家 A、10% 路由到专家 B，专家 A 的 GEMM 块是专家 B 的六倍，步进时间由专家 A 决定；若下一批路由分布反转，步进时间结构完全不同，调度器无法用历史步进时间预测下一步，批大小自适应策略失效。回滚手段是把路由统计纳入调度决策：在批形成前预估各专家的 token 数，若预估最大块超过阈值则拆分批次，用两次较小的步进换取更平稳的尾延迟。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-40\">四十 · 尾延迟：长上下文与全注意力层的耦合</h3>\n<p>尾延迟在这套实现里有两个独立来源，必须分开定位。第一个来源是序列长度：全注意力层保留压缩 KV，其注意力计算量随序列长度增长，而线性注意力层以常数级状态替代增长型 cache，计算量与长度无关。混合注意力的本意是压低平均开销，但尾延迟由最慢的那一层决定——长序列请求中全注意力层的占比虽小，其单层耗时却随长度超线性上升，成为尾部的决定性因素。第二个来源是 MoE 路由的偶发集中：即使平均路由均匀，个别步仍可能出现极端集中，这种偶发事件在长序列上被放大，因为长序列的 token 数多，路由结果的方差更大。</p>\n<p>定位尾延迟的标准做法是分位数监控而非均值监控：记录 P50、P95、P99 步进时间，并分别按序列长度分桶。若 P99 随长度桶单调上升而 P50 平稳，尾延迟来自全注意力层；若 P99 在各长度桶都偏高且与长度无关，尾延迟来自路由偶发集中。进一步的判定是看尾延迟步的专家块分布：路由集中导致的尾延迟步会伴随最大专家块 token 数激增，而全注意力层导致的尾延迟步的专家块分布正常。这个区分决定了回滚方向：前者调路由与批拆分，后者调 KV 压缩精度或对长序列请求做准入控制。</p>\n<p>系统代价上，尾延迟直接违反 SLO。材料未给出 SLO，但可以确定长上下文场景因 KV 压缩与显存限制而难以支撑高并发，尾延迟是这一约束的直接体现。具体例子：一个长序列请求进入解码循环，前若干步的全注意力层耗时随已生成 token 数增长，P99 步进时间在序列后半段抬升；若此时又有新请求加入批，批大小上升进一步挤压 KV 预算，尾延迟与 OOM 风险同时上升。回滚手段是分级准入：对超过临界长度 <span class=\"formula\">$$L^{*}$$</span> 一定比例的请求单独成批、限制并发，把尾延迟从“不可控”变为“可预算”。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-41\">四十一 · 静默降级：没有报错的性能与精度滑坡</h3>\n<p>静默降级是这套实现里最难诊断的失败模式：系统不报错、不 OOM、不崩溃，但吞吐缓慢下滑或输出质量缓慢退化。它的机制通常不是单一故障，而是多个边界条件的缓慢漂移。第一种是反量化路径的隐式降级：当显存压力上升时，内核可能选择更小的反量化块或更保守的共享内存配置，单步耗时上升但不会触发任何错误，表现为吞吐的渐进下降。第二种是 KV 压缩的精度漂移：全注意力层的压缩 KV 在长序列上累积误差，输出质量随序列长度缓慢退化，短请求正常、长请求变差，容易被误判为“长上下文能力不足”而非降级。第三种是路由统计的漂移：随着负载变化，路由分布缓慢偏移，专家负载从均匀走向集中，吞吐与尾延迟同时恶化，但每一步都在可行范围内。</p>\n<p>监控静默降级需要建立基线并做相对比较，而不是看绝对阈值。可用的指标包括：单位 token 的反量化指令数（反映内核配置是否退化）、KV 压缩后的重构误差（反映压缩精度漂移）、路由熵的滑动均值（反映负载集中趋势）。三者的共同特点是缓慢变化，因此监控窗口要足够长，采样要足够稀疏以不干扰主路径。代价是监控本身占用本就紧张的显存与带宽，在 6GB 预算下只能做低频采样，这意味着静默降级的发现存在固有延迟——这是极端受限硬件上可观测性与性能之间的硬取舍。</p>\n<p>具体例子：系统运行一段时间后，吞吐下降但无任何错误日志。排查发现反量化内核因共享内存配置被下调而使用了更小的块，单次反量化的固定开销占比上升；由于没有越过任何阈值，监控未告警。回滚手段是版本化内核配置：把反量化块大小、共享内存配置、KV 压缩精度作为一组参数固化并打标，一旦监控发现单位 token 指令数偏移，就回滚到上一组已验证配置，而不是逐项调参。这套做法的工程判断是：在无法全量观测的硬件上，可回滚的配置快照比精细的根因分析更有价值。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-42\">四十二 · 回滚策略：把失败模式映射为可执行动作</h3>\n<p>回滚不是“重启”或“换配置”这种笼统动作，而是要把每类失败模式映射到具体的、可验证的回滚单元。精度塌陷对应量化配置与路由统计的联合回滚：恢复上一组分组尺度，同时重置路由统计基线，因为误差已经改变了 token 分配，只回滚权重不足以恢复原状。OOM 对应预算配置回滚：恢复上一组批大小与序列长度上限，并检查反量化临时缓冲的释放路径是否被改动。批抖动与尾延迟对应调度配置回滚：恢复上一组容量因子、批拆分阈值与准入规则。静默降级对应内核配置快照回滚：恢复上一组反量化块大小与共享内存配置。</p>\n<p>回滚的可执行性依赖一个前提：每组配置都有对应的监控基线。设配置版本为 <span class=\"formula\">$$c$$</span>，其基线指标向量为 <span class=\"formula\">$$\\mathbf{b}_{c}$$</span>，当前指标为 <span class=\"formula\">$$\\mathbf{m}$$</span>，则回滚触发条件可写为 <span class=\"formula\">$$\\|\\mathbf{m}-\\mathbf{b}_{c}\\|&gt;\\theta$$</span>，其中 <span class=\"formula\">$$\\theta$$</span> 是按指标类型分别设定的阈值向量。这个不等式把“感觉变慢了”转化为可判定的工程条件。代价是基线本身需要存储与维护，在 6GB 显存下基线只能存放在主机侧，回滚时通过主机到设备的配置下发完成，下发本身的延迟要计入回滚时间——这是回滚策略的隐性成本。</p>\n<p>具体例子：一次精度塌陷告警触发，监控显示某层激活均值偏移且路由熵下降。按映射表执行联合回滚：恢复该层的 4-bit 分组尺度配置，同时把路由统计基线重置到上一版本。回滚后若激活均值回归基线而路由熵仍偏低，说明路由分布已被负载改变而非误差导致，此时不应继续回滚量化，而应转入批抖动诊断路径。这个分支判断是回滚策略的核心：回滚动作必须附带验证条件，验证不通过则切换到相邻的失败模式诊断，而不是反复回滚同一配置。工程判断上，极端受限硬件上的回滚优先级应高于根因分析——先恢复到已知可用状态，再在可用状态下做低频诊断，因为诊断本身会消耗本就稀缺的显存与带宽。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-43\">四十三 · 口径先于数字：这份材料能支撑什么、不能支撑什么</h3>\n<p>讨论这篇工作的性能，第一步不是看它跑得多快，而是确认它的“可引用边界”。材料给出的硬事实只有四个锚点：35B 级混合注意力 MoE、2011 年 Fermi 架构、6GB 显存、4-bit 权重。除此之外——层数、专家数、top-k、隐藏维度、批大小、上下文长度、吞吐、延迟、困惑度——全部缺失。这意味着任何“它在 X tokens/s 下达到 Y”的表述都是编造，任何“比某基线快 N 倍”的表述都不可比，因为材料明确没有给出对比基线。</p>\n<p>因此本部分的任务是建立一套读表口径：把可确认的容量结论与不可确认的性能结论严格分开。可确认的只有一件事——35B 参数以 4-bit 打包后能落入 6GB 预算并完成一次前向推理，即容量约束被满足。这是“可行性”结论，不是“效率”结论。工程读者最容易犯的错误是把可行性当成性能证据：一个模型能跑起来，与它能以可接受的 TTFT/TPOT 服务请求，是两个完全不同量级的问题。在 Blackwell 上做容量规划时，这两类结论必须分开归档。</p>\n<p>具体机制上，容量可行性的判据是权重驻留：35B 参数按 4-bit 打包，每参数 0.5 字节，权重本体约 17.5GB 量级——这个数字已经超过 6GB，说明材料所述“落入显存预算”必然依赖额外的驻留策略（分层换入、专家按需加载或类似机制），而材料未说明具体做法。这一点本身就是口径上的关键空白：不知道权重是如何在 6GB 内被组织的，就无法判断其代价落在延迟还是吞吐上。</p>\n<div class=\"formula\">$$\\text{weights}_{4bit}\\approx 35\\times10^{9}\\times 0.5\\ \\text{B}\\approx 17.5\\ \\text{GB}\\ \\gg\\ 6\\ \\text{GB}$$</div>\n<p>系统代价的直接推论：当权重本体超出显存容量近三倍时，任何“完成推理”的实现都必然引入显存与主机（或次级存储）之间的搬运，搬运带宽成为新的瓶颈，而 Fermi 时代的 PCIe 带宽与显存带宽都远低于现代平台。这不是一个可以用“手写内核优化”绕过的物理约束，而是口径上必须标注的前提。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-44\">四十四 · 硬件档位：Fermi 的四个“没有”如何定义指标含义</h3>\n<p>Fermi 档位的特殊性不在于它慢，而在于它缺少现代推理指标赖以成立的硬件前提。四个“没有”直接改写了每个指标的定义：没有张量核心，矩阵乘的算力上限由 CUDA core 的 FMA 吞吐决定；没有原生 NVFP4/FP8 路径，4-bit 权重的反量化必须由手写内核在寄存器/共享内存中完成，反量化指令本身占用发射槽；没有大容量高带宽显存，6GB 与低带宽共同把 batch 与 KV 预算压到极小；没有现代异步拷贝与流水机制，权重加载与计算的重叠能力有限。</p>\n<p>这四点决定了：在这份材料上测得的 TTFT 与 TPOT，其构成与 Blackwell 上同名指标完全不同。Blackwell 上 TTFT 主要由预填阶段的 GEMM 吞吐与 KV 写入决定，NVFP4 让权重带宽需求减半；Fermi 上 TTFT 里有一大块是反量化开销与权重搬运，这两项在 Blackwell 的 NVFP4 路径上根本不存在。把两边的 TTFT 直接并列，等于把“反量化指令开销”和“tcgen05 的 MMA 吞吐”放进同一个分子里比较，口径已经错位。</p>\n<p>具体机制上，反量化的代价可以用指令比例刻画：设每个 4-bit 权重在计算前需要一次解包与一次缩放乘，则每做一次 K 维点积，反量化指令数与 FMA 数的比值决定了内核是算力受限还是指令受限。在无张量核心的架构上，这个比值往往使内核落在指令发射受限区间，此时提升 batch 并不能线性提升吞吐——这正是“批大小受内核占用约束”的物理来源。</p>\n<div class=\"formula\">$$\\text{arithmetic intensity}=\\frac{2\\cdot M\\cdot N\\cdot K}{\\text{bytes}(W_{4bit})+\\text{bytes}(A)}\\ \\Rightarrow\\ \\text{roofline 上限}=\\min(\\text{peak FMA},\\ \\text{BW}\\times\\text{AI})$$</div>\n<p>工程判断：读这篇工作的任何性能表述时，先问“这个数字是在哪个 roofline 区间测的”。若在指令受限区，则吞吐对 batch 不敏感、对反量化实现敏感；若在带宽受限区，则吞吐对权重压缩率敏感。材料未给出这些区分，所以其数字（若有）只能作为该档位下的存在性证据，不能外推到任何其他硬件。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-45\">四十五 · batch 与并发：6GB 预算下的可行域是一条窄带</h3>\n<p>在 6GB 上，batch 不是调优参数，而是被容量方程解出来的结果。显存预算可写成权重驻留、KV cache、激活与内核工作区四项之和，其中权重项在 4-bit 下仍是最大项，KV 项随 batch 与上下文长度线性增长，激活项随 batch 增长。混合注意力的作用正是压住第二项：全注意力层保留压缩 KV，线性注意力层以常数级状态替代增长型 cache，使 KV 随序列长度的增长从线性降为部分常数。但材料未给出全注意力与线性层的比例，也未给出 KV 压缩精度，因此这条预算方程无法被数值求解。</p>\n<p>并发维度上，材料明确单卡 6GB 下不涉及专家并行与 All-to-All，专家权重全部驻留本地，通信开销为零。这是一个重要的口径特征：在这份材料里，“并发”只指请求级并发映射到极小 batch 的能力，与 Blackwell 上 NVL72 机架级的分离式预填/解码、跨节点 KV 传输完全不是同一个问题。把它的并发结论与 NVL72 的并发能力并列，属于跨档位误读。</p>\n<p>具体机制上，逐 token 解码循环中每一步都要为当前 batch 的每个 token 完成路由、按专家重排、分组 GEMM 与加权写回。分组 GEMM 的效率取决于每个专家分到的 token 数：batch 越小，单专家 token 块越窄，GEMM 的 N 维越小，内核启动与权重加载的固定开销占比越高。这就是“批大小受显存与内核占用双重约束”的机制解释——不是显存单独限制 batch，而是小 batch 下分组 GEMM 的效率塌陷反过来限制了提高 batch 的收益。</p>\n<p>系统代价：在这条窄带上，TPOT 对 batch 的敏感度远高于常规 serving。增大 batch 会同时抬高 KV 占用（逼近 6GB 上限）与单步计算量（拉长 TPOT），而减小 batch 会让分组 GEMM 落入低效区。可行域因此是一条窄带而非一个最优点，材料未给出这条窄带的位置，工程上只能定性判断：长上下文与高并发在此档位上难以同时满足。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-46\">四十六 · 指标读法：TTFT/TPOT/吞吐/显存/功耗各自的有效性</h3>\n<p>五个指标在这份材料上的有效性并不相同，需要逐项标注口径。</p>\n<ul>\n<li><b>TTFT</b>：在逐 token 解码、无分离式预填的架构下，TTFT 与首步解码的边界模糊；材料未给出请求长度分布，TTFT 无法归一化。有效性：低，仅能定性说“受权重搬运与反量化开销主导”。</li>\n<li><b>TPOT</b>：这是该档位最有意义的指标，因为它直接反映单步解码中反量化 + 分组 GEMM + 路由重排的合成代价。但材料未给出数值，只能确认其构成项。有效性：中，可作机制分析，不可作横向比较。</li>\n<li><b>吞吐</b>：材料明确未给出吞吐数字。在 batch 被容量锁死的前提下，吞吐上限由“每步可容纳的 token 数 ÷ 单步耗时”决定，两项都未知。有效性：零，不可引用。</li>\n<li><b>显存</b>：唯一有硬锚点的指标——6GB 是给定事实，4-bit 是给定事实，容量约束被满足是可确认结论。有效性：高，但只能支撑“装得下”，不能支撑“装得高效”。</li>\n<li><b>功耗</b>：材料完全未涉及。Fermi 档位的功耗特性与现代数据中心 GPU 的功耗管理（DVFS、功耗封顶下的吞吐折损）不可比，此项应直接标注为不可用。</li>\n</ul>\n<p>具体机制上，把 TPOT 拆成可归因的项有助于判断口径：单步耗时 ≈ 路由打分 + token 重排 + 逐专家权重加载与反量化 + 分组 GEMM + 加权写回 + 采样。在 Fermi 上，第二与第三项（重排与反量化）的占比显著高于现代架构，因为它们没有硬件加速路径。这解释了为什么该实现的 TPOT 不能作为“MoE 解码效率”的一般代表——它测的是手写内核在无加速硬件上的指令效率。</p>\n<p>系统代价的量化思路：若把单步耗时记为 <span>t_step</span>，则 TPOT ≈ <span>t_step</span>，而吞吐 ≈ <span>batch / t_step</span>。两个指标共享同一个分母，因此在 batch 被锁死时，提升吞吐的唯一路径是压缩 <span>t_step</span>，而 <span>t_step</span> 的下界由权重搬运带宽与反量化指令吞吐共同决定。这就是该档位的性能天花板形状：它不是一条水平线，而是一条由两个不同物理量取 min 形成的折线。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-47\">四十七 · 哪些提升不可比：四类跨档位误读</h3>\n<p>把这份材料与 Blackwell 部署并列时，有四类提升在口径上不可比，必须逐类拆开。</p>\n<ul>\n<li><b>精度路径不可比</b>：Fermi 的 4-bit 是手写反量化，Blackwell 的 NVFP4 是硬件路径加块缩放（block scaling）语义。前者把反量化成本记在指令开销里，后者把缩放记在格式里并由 tcgen05 的 MMA 直接消费。两者都叫“4-bit”，但一个的代价在发射槽，另一个的代价在格式转换与缩放因子管理。任何“4-bit 带来 N 倍加速”的说法在两边指的不是同一件事。</li>\n<li><b>KV 机制不可比</b>：混合注意力在此处是容量手段（把 KV 压进 6GB），在 Blackwell 上是延迟与吞吐手段（配合分离式预填/解码做 KV 分层与跨节点传输）。同一个结构，在两边的优化目标函数不同。</li>\n<li><b>并行拓扑不可比</b>：此处通信开销为零是因为单卡且专家全驻留；Blackwell 上的 MoE 推理必然涉及专家并行与 All-to-All，通信是吞吐方程里的一项。把“零通信”当成优势引用，等于把容量瓶颈换了个名字。</li>\n<li><b>调度不可比</b>：此处 batch 由容量解出，连续批处理与投机解码等机制在材料中未出现；Blackwell 上的批调度是在显存充裕前提下对 TTFT/TPOT 的显式权衡。两边的“batch”不是同一个决策变量。</li>\n</ul>\n<p>具体机制上，判断可比性的操作准则是：看提升的来源是否落在同一个物理量上。若来源是“减少了权重字节数”，则跨档位可比（因为带宽是共同约束）；若来源是“用硬件路径替代了手写指令”，则不可比（因为一边有该路径、一边没有）；若来源是“压缩了 KV 增长”，则需进一步看压缩比与压缩精度是否同口径。按这条准则，这份材料唯一可跨档位引用的是“4-bit 权重压缩降低带宽需求”这一层，其余全部属于档位内结论。</p>\n<p>系统代价的对照：在 Blackwell 上，NVFP4 让权重带宽需求相对 FP8 再减半，收益直接体现在 decode 阶段的显存带宽占用上；而在这份材料上，4-bit 的收益首先体现在“装得下”，其次才体现在带宽。同一个压缩率，在两个档位上被计入不同的预算科目——这是不可比性的根源，也是读表时最容易被忽略的一层。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-48\">四十八 · 读表模板：把这份材料的数字放进正确的格子</h3>\n<p>给工程读者一个可操作的口径模板：面对这份材料（以及任何缺少性能数字的极端档位工作），把结论分成三格。第一格“已确认”：35B 混合注意力 MoE 在 6GB Fermi 上以手写 4-bit CUDA 内核完成推理，容量约束被满足，单卡无通信。第二格“机制可推断”：TPOT 由反量化指令开销与权重搬运共同主导，batch 由容量方程与分组 GEMM 效率共同锁死，长上下文与高并发难以同时满足。第三格“不可引用”：吞吐、TTFT、精度代价、功耗、与任何基线的比较、以及任何“优于”表述。</p>\n<p>具体机制上，第三格的边界可以用一句话检验：材料是否给出了该指标在同一硬件档位、同一 batch、同一上下文长度下的数值？没有，就进第三格。这条检验对 Blackwell 部署同样适用——NVFP4 的吞吐数字若未标注 batch、序列长度与 KV 精度，同样不可横向比较。</p>\n<p>系统代价的落点：这份工作的工程价值不在数字，而在它把三个约束推到了极限并证明可行——权重容量、反量化指令开销、KV 增长。对 Blackwell 部署的参考意义是反向的：它告诉你当硬件缺少低精度路径时，代价会以指令开销的形式出现；因此在 Blackwell 上做容量规划时，应把 NVFP4 视为“把这项指令开销从内核里移除”的机制，而不是“又一个量化选项”。判断一个 Blackwell 推理栈是否用好了 NVFP4，看的不是它是否宣称 4-bit，而是它的 GEMM 内核里是否还存在独立的反量化 pass——存在，就说明它仍在用 Fermi 时代的口径做 Blackwell 的事。</p>\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-49\">四十九 · 迁移到 Blackwell 时真正要重写的三处</h3>\n<p>把这套方案整体搬到 B200 上，最危险的做法是把它当成“低精度内核的祖先”去致敬。它真正可迁移的只有结构决策，不是实现路径。逐项拆开看，需要重写的恰好是三处：权重的物理布局、反量化的执行位置、专家计算的聚合方式。Fermi 上权重以 4-bit 打包驻留，反量化发生在寄存器/共享内存层，靠手写指令序列把 nibble 拆成 half 再乘尺度；到了 SM100，同样的语义由 tcgen05 的 MMA 与 TMEM 承担，NVFP4 的块缩放（block scaling）在硬件路径里完成，反量化不再是“计算前的一次显式步骤”，而是被吸收进 MMA 的数据通路。这意味着原方案里最费工的那部分内核代码在 Blackwell 上不但不需要移植，移植过去反而是负收益——用软件反量化去喂一个已经支持 NVFP4 输入的 MMA，等于把硬件免费的活重新用指令做一遍。</p>\n<p>第二处是 KV 的压缩逻辑。原方案用混合注意力把 KV 增长压到 6GB 预算内，全注意力层保留压缩 KV、线性层用常数级状态替代增长型 cache。这个决策的动因是容量，不是带宽。Blackwell 上容量约束消失，KV cache 的瓶颈转为 HBM 带宽与 TMEM 占用，此时继续沿用“为省显存而牺牲注意力表达力”的混合比例就是净损失。迁移时应把混合比例当作可调参数重新标定，判据从“能否装下”换成“在目标 batch 与上下文下，全注意力层的 KV 读取带宽是否成为 decode 的临界路径”。</p>\n<p>第三处是专家聚合。原方案按路由结果把 token 重排成按专家分组的块，逐专家做分组 GEMM，本质是单卡内用时间换空间：一次只让一个专家的 4-bit 权重进入计算。SM100 上专家权重的驻留问题被更大的 HBM 与更宽的 NVLink 5 域缓解，分组 GEMM 的收益从“省显存”转为“省带宽与提利用率”，但代价结构变了——分组越细，每个 GEMM 的 M 维越小，tcgen05 的 MMA 形状利用率越差。迁移时的核心判断是：分组粒度必须与 MMA 的 tile 形状对齐，而不是与显存页对齐。</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{deq}}=\\frac{N_{\\text{w}}\\cdot c_{\\text{instr}}}{B_{\\text{HBM}}},\\qquad \\text{cost}_{\\text{mma}}=\\frac{N_{\\text{w}}\\cdot b_{\\text{weight}}}{B_{\\text{HBM}}}$$</div>\n<p>这两个式子是迁移判断的量化抓手。左式是软件反量化的代价：权重元素数乘以每元素的反量化指令周期，除以可用带宽折算成时间；右式是硬件路径下纯权重读取的代价。Fermi 上左式主导，因为 c_instr 高且无硬件低精度通路；Blackwell 上右式主导，因为 b_weight 被压到 4-bit 后，瓶颈回到“把权重从 HBM 搬进 SM”这件事本身。判断标准很直接：若左式在目标硬件上仍与右式同量级，说明软件反量化还有存在意义；若左式远小于右式，则任何手写反量化都是浪费。SM100 属于后者。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-50\">五十 · 哪些模型结构会让这套方案直接失效</h3>\n<p>原方案能成立，依赖一个未被明说但极强的前提：MoE 的专家权重可以分时复用，同一时刻只有一个（或少数几个）专家的权重需要处于“可计算”状态。这个前提在两类模型上崩掉。第一类是高 top-k、专家数少而单专家大的 MoE——路由几乎均匀打散到所有专家，分组 GEMM 退化为“每个 token 都要碰大部分专家”，分时复用的时间换空间策略失效，等价于稠密计算却背了 MoE 的调度开销。第二类是专家粒度极细、单专家参数量很小的设计，此时分组 GEMM 的 M 维被切得过碎，每次 MMA 的固定开销（权重加载、同步、路由重排）摊薄不掉。</p>\n<p>用公式刻画这个边界：设专家数为 E、top-k 为 k、单专家权重为 W_e、总权重为 W。分组 GEMM 的有效算力利用率大致正比于</p>\n<div class=\"formula\">$$\\eta\\approx\\frac{k\\cdot M_{\\text{tile}}}{k\\cdot M_{\\text{tile}}+c_{\\text{dispatch}}\\cdot E}$$</div>\n<p>其中 M_tile 是每个专家分到的 token 块的有效行数，c_dispatch 是每专家的调度与加载固定开销。k 增大或 E 增大都会压低 η。原方案在 35B 规模、材料未给出 E 与 k 的条件下能跑通，说明其 (E, k) 组合让 η 落在可接受区间；但把同一套分组 GEMM 内核套到一个 k=8、E=256 的模型上，η 会被 c_dispatch·E 项拖垮。迁移时的工程判断是：先算 η 的量级，再决定是否保留分组 GEMM，而不是默认“MoE 就该分组”。</p>\n<p>系统代价落在三处。延迟上，分组 GEMM 的尾效应（最慢专家的完成时间决定整层完成时间）在专家负载不均时放大，decode 的逐 token 循环使这种抖动无法被批内其他请求吸收。吞吐上，路由重排需要把 token 索引与激活在显存中搬运，这部分带宽开销不产生任何计算。显存上，虽然同一时刻只驻留少量专家权重，但路由表、重排缓冲与激活副本会随 batch 线性增长，在 6GB 上这是硬约束，在 Blackwell 上则转为对 TMEM 与 L2 的占用竞争。一个具体例子：把原方案迁到一个专家数翻倍、单专家减半的模型，权重总量不变、显存仍装得下，但分组 GEMM 的调用次数翻倍，每次调用的固定开销不变，总调度开销翻倍——这是容量视角完全看不到的退化。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-51\">五十一 · 规模上限：不是显存，是反量化指令吞吐与路由熵</h3>\n<p>原方案的规模上限在材料里被表述为 6GB 显存，但这只是表象。真正的上限有两个，且都随规模非线性恶化。第一个是反量化指令吞吐：Fermi 无硬件低精度通路，每读一个 4-bit 权重就要执行拆包、移位、类型转换、乘尺度这一串指令。设每元素反量化需 c 条指令、SM 的指令发射率为 I、权重元素数为 N_w，则反量化本身的时间下界是 N_w·c/I。当模型从 35B 继续增大，N_w 线性增长，而 I 是硬件常数，这个下界迟早越过显存带宽对应的下界，成为新的临界路径。材料未给出 c 与 I 的具体值，但可以定性判断：在无张量核心的架构上，反量化指令吞吐而非显存容量，才是规模继续往上推时最先撞到的墙。</p>\n<p>第二个是路由熵。MoE 的路由分布决定了分组 GEMM 的负载均衡。当专家数随规模增长、路由趋于均匀时，每个专家的 token 块变小且方差变大，分组 GEMM 的 M 维碎片化加剧，η 下降。这与显存无关，是纯调度层面的规模惩罚。迁移到 Blackwell 时这个上限不会自动消失——更大的 HBM 让权重装得下，但路由熵带来的负载不均仍然存在，只是被更宽的带宽和更高的算力部分掩盖。判断规模上限的正确姿势是同时看两条曲线：反量化/权重读取的时间下界，与分组 GEMM 有效利用率随 E、k 的衰减曲线，取两者中更早触顶的那个。</p>\n<p>一个具体机制上的例子：假设把模型从 35B 推到 70B 而架构比例不变，权重翻倍、专家数翻倍。在 Fermi 上，显存首先不够，方案直接不可行；在 Blackwell 上，显存够，但分组 GEMM 调用次数翻倍、每次 M 维减半，η 下降，同时路由重排的显存搬运量翻倍。此时系统代价的形态从“装不下”变成“装得下但吞吐被调度开销吃掉”，这是两种完全不同的失败模式，诊断手段也不同——前者看显存水位，后者看分组 GEMM 的调用计数与单次调用的有效 M 维。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-52\">五十二 · 领域迁移：哪些推理形态根本不该用这套方案</h3>\n<p>这套方案的设计中心是“单卡、容量极紧、逐 token 解码、无通信”。把它迁到七个领域时，判据不是模型大小，而是推理形态是否与这三个中心假设兼容。长上下文高并发的在线服务是最不兼容的一类：KV 随上下文线性增长，混合注意力压缩 KV 的代价是注意力表达力的损失，而在 Blackwell 上容量不再是约束，这种损失换不来任何收益，反而拉低长上下文任务的质量。这类形态应该走分离式预填/解码与 PagedAttention 路线，KV 的分层驻留与跨卡共享才是主要矛盾，4-bit 权重反量化只是次要优化。</p>\n<p>离线批量打分是另一类。它没有逐 token 解码的延迟约束，可以把 batch 推到很大，此时分组 GEMM 的固定开销被大 M 维摊薄，η 反而高。但离线场景的瓶颈通常在吞吐而非单请求延迟，原方案“一次只让少量专家权重进入计算”的分时策略会让权重反复从 HBM 搬入，带宽利用率上不去。迁移时应改为专家权重常驻、按专家做大批量 GEMM，与原方案的分时复用逻辑正好相反。这是一个典型的“同一内核、相反调度”的例子：分组 GEMM 的代码可以复用，但专家权重的驻留策略必须反转。</p>\n<p>边缘单机推理与原方案最接近，但硬件代际差异使收益结构不同。边缘设备往往有原生低精度通路（如移动 GPU 的 INT4/FP8 支持），手写反量化的必要性下降；同时边缘的功耗约束使“反量化指令吞吐”重新成为临界路径——不是因为没有硬件通路，而是因为功耗预算限制了可用的指令吞吐。这里的判断是：原方案的手写内核在边缘设备上仍有参考价值，但价值在“如何在功耗约束下组织分组 GEMM”，不在“如何手写反量化”。</p>\n<p>多卡并行形态则完全不适用。原方案明确不涉及专家并行与 All-to-All，单卡 6GB 下专家权重全部驻留本地、通信开销为零。迁到 NVL72 这类多卡域时，专家并行的 All-to-All 通信成为主导代价，分组 GEMM 的本地聚合逻辑必须让位于跨卡 dispatch/combine，原方案的内核结构无法承载通信语义。这不是“改一改”能解决的，是架构层面的不兼容。</p>\n\n<h3 id=\"paper-a-35b-hybrid-attention-mixture-of-ex-2026-sec-53\">五十三 · 迁移检查清单：把判断落到可执行的量上</h3>\n<p>给出可执行的判断而非口号，需要把上面的分析压缩成几个可在目标硬件上实测的量。第一，测软件反量化时间与权重读取时间的比值，即第一节两个式子的比。比值远小于 1 则放弃手写反量化，改用硬件 NVFP4 路径；比值接近 1 才值得保留软件路径，且应优先优化指令序列而非算法。第二，测分组 GEMM 的单次调用有效 M 维与固定开销之比，即第二节的 η。η 低于某个阈值（由目标 SLO 的延迟预算反推）则分组 GEMM 不成立，应改为稠密 GEMM 加剪枝或专家常驻。第三，测路由分布的熵与最大专家负载占比。最大负载占比过高说明尾效应主导，分组 GEMM 的并行度再高也救不了单层完成时间。</p>\n<p>这三个量共同决定迁移后的形态，而不是模型参数量。一个具体的工程判断：如果目标硬件有原生低精度 MMA、目标模型的 (E, k) 使 η 落在 0.5 以上、且推理形态是离线大批量，那么这套方案的可迁移部分只剩“按专家聚合 token”这一调度思想，内核实现应全部重写为 tcgen05 路径；反之，如果目标硬件无低精度通路、η 因小 E 小而高、推理形态是单机低并发，那么原方案的手写反量化与分时复用逻辑可以整体保留，只需按新硬件的指令吞吐重新标定分组粒度。</p>\n<p>最后落在机制上：这套方案真正的边界不在 6GB，而在“反量化指令吞吐是否仍是临界路径”与“分组 GEMM 的有效利用率是否随规模衰减到不可接受”。前者由硬件是否有原生低精度通路决定，后者由模型的 (E, k) 与路由分布决定。迁移时先测这两个量，再决定保留哪一层、重写哪一层；任何跳过测量的“整体移植”或“整体否定”，都是把工程判断换成了立场。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">A 35B Hybrid-Attention </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Mixture-of-Exper…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · A 35B Hybrid-Attention … 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出评测数据集</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出吞吐、延迟、困惑度或精度数字；可确认的是 35B 混合注意力 M…</td></tr><tr><td>消融</td><td>材料未给出消融实验；无法确认 4-bit 分组粒度、混合注意力比例或分组 …</td></tr><tr><td>局限</td><td>Fermi 无张量核心与原生低精度路径，反量化与分组 GEMM 依赖手写内…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-a-35b-hybrid-attention-mixture-of-ex-2026 · 共 9 个片段</p>\n";break;}}})();
